"""
pgmol: coordinate-only molecular Schoenflies point-group detection.

Only numpy and the Python standard library are required.
"""

from __future__ import annotations

import argparse
import math
import pathlib
import sys
from collections import defaultdict
from typing import Iterable

import numpy as np

__all__ = ["detect_point_group", "point_group"]

_EYE = np.eye(3)
_INV = -np.eye(3)


def _read_xyz(xyz_input: str | pathlib.Path) -> tuple[list[str], np.ndarray]:
    """Read an XYZ path or raw XYZ-formatted string."""
    if isinstance(xyz_input, pathlib.Path):
        text = xyz_input.read_text()
    else:
        value = str(xyz_input)
        if "\n" in value or "\r" in value:
            text = value
        else:
            path = pathlib.Path(value)
            if path.exists():
                text = path.read_text()
            else:
                raise FileNotFoundError(
                    f"{value!r} is neither an existing XYZ path nor a multiline XYZ string"
                )

    lines = text.splitlines()
    if not lines:
        raise ValueError("Empty XYZ input")

    try:
        natoms = int(lines[0].strip())
    except ValueError as exc:
        raise ValueError("First XYZ line must contain the atom count") from exc

    if natoms < 1:
        raise ValueError("XYZ atom count must be positive")
    if len(lines) < natoms + 2:
        raise ValueError("XYZ input is shorter than its declared atom count")

    symbols: list[str] = []
    coordinates: list[list[float]] = []
    for line_number, line in enumerate(lines[2 : natoms + 2], start=3):
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(f"Invalid XYZ atom line {line_number}: {line!r}")
        try:
            xyz = [float(fields[1]), float(fields[2]), float(fields[3])]
        except ValueError as exc:
            raise ValueError(f"Invalid coordinates on XYZ line {line_number}") from exc
        symbols.append(fields[0])
        coordinates.append(xyz)

    return symbols, np.asarray(coordinates, dtype=float)


def _perfect_matching(distance_matrix: np.ndarray, threshold: float) -> bool:
    """
    Determine whether every row can be assigned to a distinct compatible column.

    This small bipartite matcher avoids failure of greedy nearest-neighbour
    matching for geometrically repeated atoms.
    """
    n = distance_matrix.shape[0]
    compatible = [
        np.flatnonzero(distance_matrix[i] <= threshold).tolist() for i in range(n)
    ]
    if any(not choices for choices in compatible):
        return False

    order = sorted(range(n), key=lambda i: len(compatible[i]))
    assigned = [-1] * n

    def augment(row: int, visited: set[int]) -> bool:
        for col in compatible[row]:
            if col in visited:
                continue
            visited.add(col)
            if assigned[col] < 0 or augment(assigned[col], visited):
                assigned[col] = row
                return True
        return False

    for row in order:
        if not augment(row, set()):
            return False
    return True


def _matrix_order(matrix: np.ndarray, atol: float, maximum: int = 256) -> int | None:
    power = np.eye(3)
    for order in range(1, maximum + 1):
        power = power @ matrix
        if np.allclose(power, _EYE, atol=atol, rtol=0.0):
            return order
    return None


def _rotation_axis(matrix: np.ndarray) -> np.ndarray | None:
    """Return a normalized +1 eigenvector of a proper rotation."""
    values, vectors = np.linalg.eig(matrix)
    index = int(np.argmin(np.abs(values - 1.0)))
    if abs(values[index] - 1.0) > 1.0e-5:
        return None
    axis = np.real(vectors[:, index])
    norm = float(np.linalg.norm(axis))
    if norm < 1.0e-12:
        return None
    return axis / norm


def _mirror_normal(matrix: np.ndarray) -> np.ndarray | None:
    """Return the normal of a reflection matrix."""
    values, vectors = np.linalg.eig(matrix)
    index = int(np.argmin(np.abs(values + 1.0)))
    if abs(values[index] + 1.0) > 1.0e-5:
        return None
    normal = np.real(vectors[:, index])
    norm = float(np.linalg.norm(normal))
    if norm < 1.0e-12:
        return None
    return normal / norm


def _is_identity(matrix: np.ndarray, atol: float) -> bool:
    return bool(np.allclose(matrix, _EYE, atol=atol, rtol=0.0))


def _is_inversion(matrix: np.ndarray, atol: float) -> bool:
    return bool(np.allclose(matrix, _INV, atol=atol, rtol=0.0))


def _independent_pair(coords: np.ndarray, rank_tol: float) -> tuple[int, int]:
    """
    Select two non-collinear centered coordinate vectors.

    Molecules of rank >= 2 always possess such a pair.  Using a fixed source
    pair is sufficient: every molecular symmetry maps that pair onto an
    equivalent target pair.
    """
    nonzero = [
        i for i, point in enumerate(coords) if np.linalg.norm(point) > rank_tol
    ]
    for i in nonzero:
        for j in nonzero:
            if i >= j:
                continue
            if np.linalg.norm(np.cross(coords[i], coords[j])) > rank_tol:
                return i, j
    raise ValueError("Could not construct a non-collinear coordinate pair")


def _orthonormal_frame(u: np.ndarray, v: np.ndarray) -> np.ndarray:
    """Construct right-handed orthonormal frame whose first two directions span u,v."""
    e1 = u / np.linalg.norm(u)
    residual = v - np.dot(v, e1) * e1
    e2 = residual / np.linalg.norm(residual)
    e3 = np.cross(e1, e2)
    return np.column_stack((e1, e2, e3))


def _symmetry_operations(
    symbols: list[str],
    coords: np.ndarray,
    tol: float,
) -> list[np.ndarray]:
    """
    Enumerate all finite orthogonal operations preserving labeled coordinates.

    For rank >= 2 every operation is determined by images of two independent
    atom vectors.  Both possible images of the normal are examined, so planar
    structures and improper operations are handled without special alignment.
    """
    n = len(symbols)
    groups: dict[str, np.ndarray] = {}
    for symbol in set(symbols):
        groups[symbol] = np.asarray(
            [i for i, item in enumerate(symbols) if item == symbol], dtype=int
        )

    scale = max(1.0, float(np.max(np.linalg.norm(coords, axis=1))))
    rank_tol = max(1.0e-10, tol * 1.0e-5)
    source_i, source_j = _independent_pair(coords, rank_tol)
    source_u = coords[source_i]
    source_v = coords[source_j]
    source_frame = _orthonormal_frame(source_u, source_v)

    radius_u = float(np.linalg.norm(source_u))
    radius_v = float(np.linalg.norm(source_v))
    dot_uv = float(np.dot(source_u, source_v))
    invariant_tol = max(tol * scale * 8.0, 1.0e-10)

    candidate_matrices: list[np.ndarray] = [_EYE.copy()]
    candidates_u = groups[symbols[source_i]]
    candidates_v = groups[symbols[source_j]]

    for target_i in candidates_u:
        target_u = coords[target_i]
        if abs(np.linalg.norm(target_u) - radius_u) > invariant_tol:
            continue

        for target_j in candidates_v:
            target_v = coords[target_j]
            if abs(np.linalg.norm(target_v) - radius_v) > invariant_tol:
                continue
            if abs(float(np.dot(target_u, target_v)) - dot_uv) > invariant_tol:
                continue
            if np.linalg.norm(np.cross(target_u, target_v)) <= rank_tol:
                continue

            target_frame = _orthonormal_frame(target_u, target_v)

            for handedness in (1.0, -1.0):
                signed_target = target_frame.copy()
                signed_target[:, 2] *= handedness
                operation = signed_target @ source_frame.T
                candidate_matrices.append(operation)

    accepted: list[np.ndarray] = []
    matrix_tol = max(2.0e-7, tol / max(scale, 1.0) * 0.2)

    for operation in candidate_matrices:
        if not np.allclose(operation.T @ operation, _EYE, atol=1.0e-7, rtol=0.0):
            continue

        valid = True
        transformed = coords @ operation.T
        for symbol, indices in groups.items():
            source_points = transformed[indices]
            target_points = coords[indices]
            differences = source_points[:, None, :] - target_points[None, :, :]
            distances = np.linalg.norm(differences, axis=2)
            if not _perfect_matching(distances, tol):
                valid = False
                break

        if not valid:
            continue

        if not any(np.allclose(operation, old, atol=matrix_tol, rtol=0.0) for old in accepted):
            accepted.append(operation)

    if not any(_is_identity(op, matrix_tol) for op in accepted):
        accepted.append(_EYE.copy())
    return accepted


def _classify_operations(operations: Iterable[np.ndarray], tol: float) -> str:
    operations = list(operations)
    matrix_tol = max(2.0e-6, tol * 0.2)

    proper = [op for op in operations if np.linalg.det(op) > 0.0]
    improper = [op for op in operations if np.linalg.det(op) < 0.0]

    proper_orders: list[tuple[np.ndarray, int]] = []
    for op in proper:
        order = _matrix_order(op, matrix_tol)
        if order is not None:
            proper_orders.append((op, order))

    max_proper_order = max((order for _, order in proper_orders), default=1)
    proper_count = len(proper)
    inversion = any(_is_inversion(op, matrix_tol) for op in improper)

    mirrors: list[tuple[np.ndarray, np.ndarray]] = []
    for op in improper:
        if _matrix_order(op, matrix_tol) == 2 and not _is_inversion(op, matrix_tol):
            normal = _mirror_normal(op)
            if normal is not None:
                mirrors.append((op, normal))

    # Cubic / icosahedral groups are recognized from their finite proper
    # rotational subgroup, not from inertia tensor degeneracy.
    if proper_count == 60 and max_proper_order == 5:
        return "Ih" if inversion else "I"
    if proper_count == 24 and max_proper_order == 4:
        return "Oh" if inversion else "O"
    if proper_count == 12 and max_proper_order == 3:
        if not improper:
            return "T"
        return "Th" if inversion else "Td"

    if proper_count == 1:
        if not improper:
            return "C1"
        if mirrors:
            return "Cs"
        if inversion:
            return "Ci"
        improper_orders = [
            order
            for op in improper
            if (order := _matrix_order(op, matrix_tol)) is not None and order > 2
        ]
        return f"S{max(improper_orders)}" if improper_orders else "C1"

    # Main proper rotational axis.  For D2-like groups any of the equivalent
    # C2 axes works; horizontal/vertical mirror tests remain valid.
    principal_axis: np.ndarray | None = None
    for op, order in proper_orders:
        if order == max_proper_order and order > 1:
            principal_axis = _rotation_axis(op)
            if principal_axis is not None:
                break

    n = max_proper_order
    is_dihedral = proper_count == 2 * n and n >= 2

    if is_dihedral:
        if not improper:
            return f"D{n}"

        horizontal = False
        if principal_axis is not None:
            for _, normal in mirrors:
                if abs(float(np.dot(normal, principal_axis))) > 0.85:
                    horizontal = True
                    break

        if horizontal:
            return f"D{n}h"
        if mirrors:
            return f"D{n}d"

        # A full dihedral extension normally contains mirrors if it contains
        # improper operations.  This fallback is chiefly defensive for noisy
        # borderline inputs.
        return f"D{n}h" if inversion else f"D{n}d"

    # Cyclic groups and pure improper-rotation groups.
    if not improper:
        return f"C{n}"

    if mirrors:
        horizontal = False
        if principal_axis is not None:
            for _, normal in mirrors:
                if abs(float(np.dot(normal, principal_axis))) > 0.85:
                    horizontal = True
                    break
        return f"C{n}h" if horizontal else f"C{n}v"

    improper_orders = [
        order
        for op in improper
        if (order := _matrix_order(op, matrix_tol)) is not None and order > 2
    ]
    if improper_orders:
        return f"S{max(improper_orders)}"

    if inversion and n == 1:
        return "Ci"
    return f"C{n}"


def detect_point_group(xyz_input: str | pathlib.Path, tol: float = 1e-2) -> str:
    """
    Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input : str | pathlib.Path
        Path to an XYZ file OR a raw XYZ-formatted multiline string.
    tol : float, optional
        Cartesian distance tolerance in angstroms (default: 1e-2).

    Returns
    -------
    str
        Exact ASCII Schoenflies point-group symbol.
    """
    if tol <= 0:
        raise ValueError("tol must be positive")

    symbols, coordinates = _read_xyz(xyz_input)
    natoms = len(symbols)

    if natoms == 1:
        return "Kh"

    # The centroid is invariant under every symmetry operation because any
    # allowed operation only permutes atoms.  Equal weighting is intentional:
    # no isotope or atomic-mass assumptions are needed.
    coords = coordinates - np.mean(coordinates, axis=0)

    singular_values = np.linalg.svd(coords, compute_uv=False)
    scale = max(1.0, float(singular_values[0]))
    rank_threshold = max(1.0e-10, tol * 1.0e-5 * scale)
    rank = int(np.count_nonzero(singular_values > rank_threshold))

    if rank <= 1:
        # Every finite linear molecular geometry has an infinite principal
        # rotational axis.  Inversion distinguishes Dinfh from Cinfv.
        by_symbol: defaultdict[str, list[np.ndarray]] = defaultdict(list)
        for symbol, point in zip(symbols, coords):
            by_symbol[symbol].append(point)

        inverted = True
        for points in by_symbol.values():
            array = np.asarray(points)
            distances = np.linalg.norm(
                (-array)[:, None, :] - array[None, :, :], axis=2
            )
            if not _perfect_matching(distances, tol):
                inverted = False
                break
        return "Dinfh" if inverted else "Cinfv"

    operations = _symmetry_operations(symbols, coords, tol)
    return _classify_operations(operations, tol)


point_group = detect_point_group


def main(argv: list[str] | None = None) -> int:
    """CLI entry point for ``pgmol`` and ``python -m pgmol``."""
    parser = argparse.ArgumentParser(
        prog="pgmol",
        description="Determine a molecule's Schoenflies point group from an XYZ file.",
    )
    parser.add_argument("xyz", type=pathlib.Path, help="Path to an XYZ file")
    parser.add_argument(
        "--tol",
        type=float,
        default=1e-2,
        help="Cartesian matching tolerance in angstroms (default: 1e-2)",
    )
    args = parser.parse_args(argv)
    print(detect_point_group(args.xyz, tol=args.tol))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""pgmol: Schoenflies point-group detection from XYZ coordinates.

Only the Python standard library and numpy are used.  Classification depends
solely on element labels and Cartesian coordinates.  The method:

1. Centre the molecule on its unweighted centroid (fixed by every symmetry
   operation that permutes like-labelled atoms).
2. Detect linear molecules directly (Dinfh / Cinfv).
3. Otherwise enumerate *all* orthogonal operations that map the molecule onto
   itself.  Two non-collinear reference atoms i, j are fixed; every candidate
   image pair (a, b) with matching labels and norms yields exactly one proper
   and one improper orthogonal map.  Each map is orthogonalised (polar
   decomposition) and verified against every atom within ``tol``.
4. Classify the resulting finite group from element orders, the number of
   proper rotations of each order, and the presence of inversion, reflections
   and rotation-reflection elements.
"""
from __future__ import annotations

import pathlib
import sys
from typing import Iterable, List, Sequence, Tuple, Union

import numpy as np

__all__ = ["detect_point_group", "point_group", "main"]

# Tolerance for dimensionless matrix comparisons (orders, identities, axes).
_MAT_ATOL = 0.1
_I3 = np.eye(3)
_MAX_ORDER = 120


# ---------------------------------------------------------------------------
# Input handling
# ---------------------------------------------------------------------------
def _read_text(xyz_input: Union[str, pathlib.Path]) -> str:
    if isinstance(xyz_input, pathlib.Path):
        return xyz_input.read_text()
    text = str(xyz_input)
    if "\n" not in text and text.strip():
        candidate = pathlib.Path(text.strip())
        try:
            if candidate.is_file():
                return candidate.read_text()
        except (OSError, ValueError):
            pass
    return text


def _normalise_symbol(sym: str) -> str:
    sym = sym.strip()
    if sym.isdigit():
        return sym
    return sym[0].upper() + sym[1:].lower()


def _parse_xyz(text: str) -> Tuple[List[str], np.ndarray]:
    lines = text.splitlines()
    i = 0
    while i < len(lines) and not lines[i].strip():
        i += 1
    if i >= len(lines):
        raise ValueError("empty XYZ input")
    try:
        n = int(lines[i].split()[0])
    except (ValueError, IndexError) as exc:
        raise ValueError("first XYZ line must contain the number of atoms") from exc
    if n < 1:
        raise ValueError("XYZ input must contain at least one atom")

    symbols: List[str] = []
    coords: List[List[float]] = []
    k = i + 2  # line i+1 is the comment line and is ignored
    while len(symbols) < n and k < len(lines):
        parts = lines[k].split()
        k += 1
        if not parts:
            continue
        if len(parts) < 4:
            raise ValueError(f"malformed atom line: {lines[k - 1]!r}")
        symbols.append(_normalise_symbol(parts[0]))
        coords.append([float(x) for x in parts[1:4]])
    if len(symbols) != n:
        raise ValueError(f"expected {n} atoms, found {len(symbols)}")
    return symbols, np.asarray(coords, dtype=float)


# ---------------------------------------------------------------------------
# Geometry helpers
# ---------------------------------------------------------------------------
def _maps_onto(O: np.ndarray, r: np.ndarray, types: np.ndarray, tol: float) -> bool:
    """True if the orthogonal map O sends every atom onto a like-labelled atom."""
    p = r @ O.T
    d = np.linalg.norm(p[:, None, :] - r[None, :, :], axis=2)
    same = types[:, None] == types[None, :]
    d = np.where(same, d, np.inf)
    return bool(np.all(d.min(axis=1) < tol))


def _symmetry_operations(r: np.ndarray, types: np.ndarray, tol: float) -> List[np.ndarray]:
    """Return every orthogonal matrix that leaves the (centred) molecule invariant."""
    n = len(r)
    norms = np.linalg.norm(r, axis=1)
    i = int(np.argmax(norms))
    cross_norms = np.linalg.norm(np.cross(r[i], r), axis=1)
    j = int(np.argmax(cross_norms))
    ni = np.cross(r[i], r[j])
    F = np.column_stack([r[i], r[j], ni])
    Finv = np.linalg.inv(F)

    ops: List[np.ndarray] = []
    seen = set()
    for a in range(n):
        if types[a] != types[i] or abs(norms[a] - norms[i]) > tol:
            continue
        for b in range(n):
            if types[b] != types[j] or abs(norms[b] - norms[j]) > tol:
                continue
            na = np.cross(r[a], r[b])
            for s in (1.0, -1.0):
                T = np.column_stack([r[a], r[b], s * na])
                U, _, Vt = np.linalg.svd(T @ Finv)
                O = U @ Vt
                key = tuple(np.round(O, 4).ravel())
                if key in seen:
                    continue
                seen.add(key)
                if _maps_onto(O, r, types, tol):
                    ops.append(O)
    return ops


# ---------------------------------------------------------------------------
# Group classification
# ---------------------------------------------------------------------------
def _order(M: np.ndarray) -> int:
    P = M.copy()
    for k in range(1, _MAX_ORDER + 1):
        if np.max(np.abs(P - _I3)) < _MAT_ATOL:
            return k
        P = P @ M
    return 0


def _rotation_axis(R: np.ndarray) -> np.ndarray:
    _, _, vt = np.linalg.svd(R - _I3)
    return vt[-1]


def _classify(ops: Sequence[np.ndarray]) -> str:
    entries = []
    for M in ops:
        d = float(np.linalg.det(M))
        entries.append((M, d > 0, _order(M)))

    proper = [(M, o) for M, p, o in entries if p]
    improper = [(M, o) for M, p, o in entries if not p]
    has_inv = any(np.max(np.abs(M + _I3)) < _MAT_ATOL for M, _ in improper)
    has_improper = len(improper) > 0

    count3 = sum(1 for _, o in proper if o == 3)
    count4 = sum(1 for _, o in proper if o == 4)
    count5 = sum(1 for _, o in proper if o == 5)

    # --- polyhedral groups -------------------------------------------------
    if count3 >= 8 and count5 > 0:
        return "Ih" if has_improper else "I"
    if count3 >= 8:
        if count4 > 0:
            return "Oh" if has_improper else "O"
        if has_improper:
            return "Th" if has_inv else "Td"
        return "T"

    # --- axial and low-symmetry groups ------------------------------------
    nmax = max((o for _, o in proper), default=1)
    if nmax >= 3:
        axis_elem = next(M for M, o in proper if o == nmax)
        k = _rotation_axis(axis_elem)
        return _classify_high(nmax, k, proper, improper, has_inv)
    return _classify_low(len(ops), proper, improper, has_inv)


def _classify_high(n: int, k: np.ndarray, proper, improper, has_inv: bool) -> str:
    c2perp = any(
        o == 2 and np.linalg.norm(M @ k + k) < _MAT_ATOL for M, o in proper
    )
    sh = sv = False
    s_type = False
    for M, o in improper:
        if np.max(np.abs(M + _I3)) < _MAT_ATOL:
            continue  # inversion, handled by has_inv
        if o == 2:
            if np.linalg.norm(M @ k + k) < _MAT_ATOL:
                sh = True
            elif np.linalg.norm(M @ k - k) < _MAT_ATOL:
                sv = True
        else:
            s_type = True

    if not improper:
        return f"D{n}" if c2perp else f"C{n}"

    if c2perp:
        if sh and sv:
            return f"D{n}h"
        if sh:
            return f"D{n}h"
        return f"D{n}d"

    if sh:
        return f"C{n}h"
    if sv:
        return f"C{n}v"
    # Only rotation-reflection (S_2m) elements remain.
    return f"S{2 * n}"


def _classify_low(h: int, proper, improper, has_inv: bool) -> str:
    nC2 = sum(1 for _, o in proper if o == 2)
    refl = sum(1 for M, o in improper
               if o == 2 and np.max(np.abs(M + _I3)) >= _MAT_ATOL)
    nS = sum(1 for M, o in improper
             if o != 2)

    if h == 1:
        return "C1"
    if h == 2:
        if nC2:
            return "C2"
        if has_inv:
            return "Ci"
        return "Cs"
    if h == 4:
        if nC2 == 3:
            return "D2"
        if has_inv:
            return "C2h"
        if refl == 2:
            return "C2v"
        if nS > 0:
            return "S4"
        return "C2v"
    if h == 8:
        return "D2h" if has_inv else "D2d"
    return "C1"


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def detect_point_group(xyz_input: Union[str, pathlib.Path], tol: float = 1e-2) -> str:
    """
    Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input : str | pathlib.Path
        Path to an XYZ file OR a raw XYZ-formatted multiline string.
    tol : float, optional
        Cartesian distance tolerance in angstroms (default: 1e-2).

    Returns
    -------
    str
        Exact ASCII Schoenflies symbol, e.g. 'C1', 'Cs', 'Ci', 'C2', 'C2v',
        'C3h', 'D2h', 'D3d', 'S4', 'T', 'Td', 'Th', 'O', 'Oh', 'I', 'Ih',
        'Cinfv', 'Dinfh', or 'Kh'.
    """
    symbols, coords = _parse_xyz(_read_text(xyz_input))
    tol = float(tol)
    if len(symbols) == 1:
        return "Kh"

    types = np.array(symbols)
    r = coords - coords.mean(axis=0)
    if np.linalg.norm(r, axis=1).max() < tol:
        return "Kh"

    # Linear molecules
    _, _, vt = np.linalg.svd(r, full_matrices=False)
    u = vt[0]
    perp = r - np.outer(r @ u, u)
    if np.linalg.norm(perp, axis=1).max() < tol:
        return "Dinfh" if _maps_onto(-_I3, r, types, tol) else "Cinfv"

    ops = _symmetry_operations(r, types, tol)
    if not ops:
        return "C1"
    return _classify(ops)


point_group = detect_point_group


def main(argv: Iterable[str] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 1 or args[0] in ("-h", "--help"):
        print("usage: pgmol <file.xyz>", file=sys.stderr)
        return 0 if args and args[0] in ("-h", "--help") else 2
    print(detect_point_group(pathlib.Path(args[0])))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Coordinate-based molecular Schoenflies point-group detection.

This module requires only NumPy and the Python standard library.
"""

from __future__ import annotations

import argparse
import pathlib
from collections.abc import Sequence

import numpy as np

__all__ = ["detect_point_group", "point_group", "main"]


def _read_xyz(xyz_input: str | pathlib.Path) -> tuple[list[str], np.ndarray]:
    if isinstance(xyz_input, pathlib.Path):
        text = xyz_input.read_text(encoding="utf-8")
    elif isinstance(xyz_input, str):
        if "\n" in xyz_input or "\r" in xyz_input:
            text = xyz_input
        else:
            try:
                path = pathlib.Path(xyz_input)
                text = (
                    path.read_text(encoding="utf-8")
                    if path.is_file()
                    else xyz_input
                )
            except (OSError, ValueError):
                text = xyz_input
    else:
        raise TypeError("xyz_input must be a string or pathlib.Path")

    lines = text.lstrip("\ufeff").splitlines()
    if not lines:
        raise ValueError("Empty XYZ input")

    try:
        atom_count = int(lines[0].strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("The first XYZ line must contain the atom count") from exc

    if atom_count < 1:
        raise ValueError("An XYZ structure must contain at least one atom")
    if len(lines) < atom_count + 2:
        raise ValueError(
            f"XYZ input declares {atom_count} atoms but contains too few lines"
        )

    symbols: list[str] = []
    coordinates: list[list[float]] = []

    # Line 2 is deliberately ignored in its entirety.
    for line_number, line in enumerate(lines[2 : atom_count + 2], start=3):
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(f"Invalid XYZ atom record on line {line_number}")

        symbol = fields[0]
        if not symbol:
            raise ValueError(f"Missing element symbol on line {line_number}")
        symbol = symbol[0].upper() + symbol[1:].lower()

        try:
            xyz = [float(fields[1]), float(fields[2]), float(fields[3])]
        except ValueError as exc:
            raise ValueError(
                f"Invalid Cartesian coordinate on line {line_number}"
            ) from exc

        if not np.all(np.isfinite(xyz)):
            raise ValueError(
                f"Non-finite Cartesian coordinate on line {line_number}"
            )

        symbols.append(symbol)
        coordinates.append(xyz)

    return symbols, np.asarray(coordinates, dtype=float)


def _perfect_matching(
    transformed: np.ndarray,
    target: np.ndarray,
    symbols: Sequence[str],
    tolerance: float,
) -> np.ndarray | None:
    """Find a symbol-preserving perfect matching within a distance threshold."""
    count = len(symbols)
    mapping = np.full(count, -1, dtype=int)

    symbol_groups: dict[str, list[int]] = {}
    for index, symbol in enumerate(symbols):
        symbol_groups.setdefault(symbol, []).append(index)

    tolerance_squared = tolerance * tolerance

    for indices in symbol_groups.values():
        source_indices = np.asarray(indices, dtype=int)
        target_indices = np.asarray(indices, dtype=int)

        difference = (
            transformed[source_indices, None, :]
            - target[target_indices][None, :, :]
        )
        distance_squared = np.einsum(
            "ijk,ijk->ij", difference, difference, optimize=True
        )

        adjacency = [
            list(np.flatnonzero(distance_squared[row] <= tolerance_squared))
            for row in range(len(indices))
        ]
        if any(not neighbors for neighbors in adjacency):
            return None

        # Match the most constrained atoms first.
        row_order = sorted(range(len(indices)), key=lambda row: len(adjacency[row]))
        matched_row_for_column = [-1] * len(indices)

        def augment(row: int, visited: list[bool]) -> bool:
            neighbors = sorted(
                adjacency[row],
                key=lambda column: distance_squared[row, column],
            )
            for column in neighbors:
                if visited[column]:
                    continue
                visited[column] = True
                previous = matched_row_for_column[column]
                if previous == -1 or augment(previous, visited):
                    matched_row_for_column[column] = row
                    return True
            return False

        for row in row_order:
            if not augment(row, [False] * len(indices)):
                return None

        for column, local_row in enumerate(matched_row_for_column):
            mapping[source_indices[local_row]] = target_indices[column]

    return mapping


def _orthogonal_fit(
    source: np.ndarray,
    target: np.ndarray,
    mapping: np.ndarray,
    determinant: int,
) -> np.ndarray:
    """Fit Q in Q @ source_i ~= target_mapping[i], fixing det(Q)."""
    covariance = source.T @ target[mapping]
    left, _, right_transpose = np.linalg.svd(covariance)

    row_transform = left @ right_transpose
    if np.linalg.det(row_transform) * determinant < 0.0:
        correction = np.eye(3)
        correction[-1, -1] = -1.0
        row_transform = left @ correction @ right_transpose

    return row_transform.T


def _refine_operation(
    initial: np.ndarray,
    coordinates: np.ndarray,
    symbols: Sequence[str],
    tolerance: float,
) -> np.ndarray | None:
    determinant = 1 if np.linalg.det(initial) >= 0.0 else -1
    operation = initial

    # A generous preliminary threshold allows the atom-defined frame to be
    # polished by an all-atom orthogonal Procrustes fit.
    preliminary_tolerance = max(4.0 * tolerance, 1.0e-9)

    for _ in range(3):
        transformed = coordinates @ operation.T
        mapping = _perfect_matching(
            transformed, coordinates, symbols, preliminary_tolerance
        )
        if mapping is None:
            return None
        operation = _orthogonal_fit(
            coordinates, coordinates, mapping, determinant
        )

    transformed = coordinates @ operation.T
    mapping = _perfect_matching(
        transformed,
        coordinates,
        symbols,
        tolerance * (1.0 + 1.0e-9) + 1.0e-10,
    )
    if mapping is None:
        return None

    operation = _orthogonal_fit(coordinates, coordinates, mapping, determinant)
    transformed = coordinates @ operation.T
    if (
        _perfect_matching(
            transformed,
            coordinates,
            symbols,
            tolerance * (1.0 + 1.0e-9) + 1.0e-10,
        )
        is None
    ):
        return None

    return operation


def _is_duplicate(
    operation: np.ndarray,
    operations: Sequence[np.ndarray],
    threshold: float,
) -> bool:
    return any(np.linalg.norm(operation - other, ord="fro") <= threshold
               for other in operations)


def _find_frame(coordinates: np.ndarray, tolerance: float) -> tuple[int, int] | None:
    """Choose a numerically stable ordered pair of non-collinear atom vectors."""
    count = len(coordinates)
    best_pair: tuple[int, int] | None = None
    best_score = -1.0

    for first in range(count):
        norm_first = float(np.linalg.norm(coordinates[first]))
        if norm_first <= 1.0e-14:
            continue
        for second in range(count):
            if first == second:
                continue
            norm_second = float(np.linalg.norm(coordinates[second]))
            if norm_second <= 1.0e-14:
                continue

            cross_norm = float(
                np.linalg.norm(np.cross(coordinates[first], coordinates[second]))
            )
            score = cross_norm / max(norm_first, norm_second)
            if score > best_score:
                best_score = score
                best_pair = (first, second)

    if best_pair is None or best_score <= max(tolerance, 1.0e-10):
        return None
    return best_pair


def _basis(first: np.ndarray, second: np.ndarray) -> np.ndarray | None:
    norm_first = float(np.linalg.norm(first))
    if norm_first <= 1.0e-14:
        return None

    e1 = first / norm_first
    perpendicular = second - np.dot(second, e1) * e1
    perpendicular_norm = float(np.linalg.norm(perpendicular))
    if perpendicular_norm <= 1.0e-14:
        return None

    e2 = perpendicular / perpendicular_norm
    e3 = np.cross(e1, e2)
    return np.column_stack((e1, e2, e3))


def _enumerate_operations(
    coordinates: np.ndarray,
    symbols: Sequence[str],
    tolerance: float,
) -> list[np.ndarray]:
    identity = np.eye(3)
    operations: list[np.ndarray] = [identity]

    frame_indices = _find_frame(coordinates, tolerance)
    if frame_indices is None:
        return operations

    first, second = frame_indices
    source_basis = _basis(coordinates[first], coordinates[second])
    if source_basis is None:
        return operations

    scale = max(float(np.max(np.linalg.norm(coordinates, axis=1))), tolerance)
    duplicate_threshold = max(1.0e-6, min(2.0e-3, tolerance / scale * 0.05))

    first_targets = [
        index for index, symbol in enumerate(symbols)
        if symbol == symbols[first]
    ]
    second_targets = [
        index for index, symbol in enumerate(symbols)
        if symbol == symbols[second]
    ]

    for target_first in first_targets:
        for target_second in second_targets:
            if target_first == target_second:
                continue

            target_basis = _basis(
                coordinates[target_first], coordinates[target_second]
            )
            if target_basis is None:
                continue

            for determinant in (1, -1):
                handedness = np.diag([1.0, 1.0, float(determinant)])
                candidate = target_basis @ handedness @ source_basis.T
                refined = _refine_operation(
                    candidate, coordinates, symbols, tolerance
                )
                if refined is None:
                    continue
                if not _is_duplicate(refined, operations, duplicate_threshold):
                    operations.append(refined)

    return operations


def _operation_order(operation: np.ndarray, maximum: int = 240) -> int:
    identity = np.eye(3)
    power = np.eye(3)
    for order in range(1, maximum + 1):
        power = power @ operation
        if np.linalg.norm(power - identity, ord="fro") <= 5.0e-3:
            return order
    return maximum + 1


def _proper_axis(operation: np.ndarray) -> np.ndarray:
    values, vectors = np.linalg.eig(operation)
    index = int(np.argmin(np.abs(values - 1.0)))
    axis = np.real(vectors[:, index])
    axis /= np.linalg.norm(axis)
    return axis


def _improper_axis(operation: np.ndarray) -> np.ndarray:
    values, vectors = np.linalg.eig(operation)
    index = int(np.argmin(np.abs(values + 1.0)))
    axis = np.real(vectors[:, index])
    axis /= np.linalg.norm(axis)
    return axis


def _is_inversion(operation: np.ndarray) -> bool:
    return np.linalg.norm(operation + np.eye(3), ord="fro") <= 5.0e-3


def _is_reflection(operation: np.ndarray) -> bool:
    if np.linalg.det(operation) >= 0.0:
        return False
    return (
        _operation_order(operation) == 2
        and not _is_inversion(operation)
        and abs(float(np.trace(operation)) - 1.0) <= 1.0e-2
    )


def _reflection_normal(operation: np.ndarray) -> np.ndarray:
    values, vectors = np.linalg.eigh((operation + operation.T) * 0.5)
    index = int(np.argmin(values))
    normal = vectors[:, index]
    normal /= np.linalg.norm(normal)
    return normal


def _has_horizontal_reflection(
    improper: Sequence[np.ndarray], axis: np.ndarray
) -> bool:
    for operation in improper:
        if not _is_reflection(operation):
            continue
        alignment = abs(float(np.dot(_reflection_normal(operation), axis)))
        if alignment >= 0.9:
            return True
    return False


def _has_vertical_reflection(
    improper: Sequence[np.ndarray], axis: np.ndarray
) -> bool:
    for operation in improper:
        if not _is_reflection(operation):
            continue
        alignment = abs(float(np.dot(_reflection_normal(operation), axis)))
        if alignment <= 0.1:
            return True
    return False


def _classify_finite(operations: Sequence[np.ndarray]) -> str:
    proper = [
        operation for operation in operations
        if np.linalg.det(operation) >= 0.0
    ]
    improper = [
        operation for operation in operations
        if np.linalg.det(operation) < 0.0
    ]

    proper_orders = [_operation_order(operation) for operation in proper]
    proper_order_set = set(proper_orders)
    proper_count = len(proper)
    inversion = any(_is_inversion(operation) for operation in improper)

    # Identify polyhedral groups from the full proper-rotation subgroup rather
    # than from inertia degeneracies. This avoids accidental spherical tops.
    if (
        proper_count == 60
        and proper_order_set == {1, 2, 3, 5}
    ):
        return "Ih" if improper else "I"

    if (
        proper_count == 24
        and proper_order_set == {1, 2, 3, 4}
    ):
        return "Oh" if improper else "O"

    if (
        proper_count == 12
        and proper_order_set == {1, 2, 3}
    ):
        if not improper:
            return "T"
        return "Th" if inversion else "Td"

    nonidentity_proper = [
        (operation, order)
        for operation, order in zip(proper, proper_orders)
        if order > 1
    ]

    if not nonidentity_proper:
        if not improper:
            return "C1"
        if inversion:
            return "Ci"
        return "Cs"

    main_operation, n = max(nonidentity_proper, key=lambda item: item[1])
    axis = _proper_axis(main_operation)

    # In D2d, all proper C2 axes have the same order. The S4 axis selects the
    # conventional principal axis and prevents a spurious D2h assignment.
    if n == 2:
        higher_improper = [
            operation
            for operation in improper
            if _operation_order(operation) > 2
        ]
        if higher_improper:
            axis = _improper_axis(
                max(higher_improper, key=_operation_order)
            )

    is_dihedral = (
        proper_count >= 4 if n == 2 else proper_count >= 2 * n
    )

    horizontal = _has_horizontal_reflection(improper, axis)
    vertical = _has_vertical_reflection(improper, axis)

    if is_dihedral:
        if not improper:
            return f"D{n}"
        if horizontal:
            return f"D{n}h"
        return f"D{n}d"

    if not improper:
        return f"C{n}"
    if vertical:
        return f"C{n}v"
    if horizontal:
        return f"C{n}h"

    improper_orders = [_operation_order(operation) for operation in improper]
    s_order = max(improper_orders)
    return f"S{s_order}"


def _is_linear(coordinates: np.ndarray, tolerance: float) -> bool:
    radii = np.linalg.norm(coordinates, axis=1)
    farthest = int(np.argmax(radii))
    if radii[farthest] <= tolerance:
        return True

    axis = coordinates[farthest] / radii[farthest]
    projections = coordinates @ axis
    perpendicular = coordinates - projections[:, None] * axis
    maximum_deviation = float(np.max(np.linalg.norm(perpendicular, axis=1)))
    return maximum_deviation <= tolerance


def _has_linear_inversion(
    coordinates: np.ndarray,
    symbols: Sequence[str],
    tolerance: float,
) -> bool:
    return (
        _perfect_matching(
            -coordinates,
            coordinates,
            symbols,
            tolerance * (1.0 + 1.0e-9) + 1.0e-10,
        )
        is not None
    )


def detect_point_group(
    xyz_input: str | pathlib.Path,
    tol: float = 1e-2,
) -> str:
    """
    Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input : str | pathlib.Path
        Path to an XYZ file OR a raw XYZ-formatted multiline string.
    tol : float, optional
        Cartesian distance tolerance in ångströms (default: 1e-2).

    Returns
    -------
    str
        Exact ASCII Schoenflies point-group symbol.
    """
    if not isinstance(tol, (int, float, np.integer, np.floating)):
        raise TypeError("tol must be a positive real number")
    tolerance = float(tol)
    if not np.isfinite(tolerance) or tolerance <= 0.0:
        raise ValueError("tol must be a positive finite number")

    symbols, coordinates = _read_xyz(xyz_input)

    if len(symbols) == 1:
        return "Kh"

    # Every symmetry of a finite point set fixes its unweighted centroid.
    # Using the geometric rather than mass-weighted centroid also avoids any
    # dependency on an external isotope or atomic-mass table.
    coordinates = coordinates - np.mean(coordinates, axis=0)

    if _is_linear(coordinates, tolerance):
        if _has_linear_inversion(coordinates, symbols, tolerance):
            return "Dinfh"
        return "Cinfv"

    operations = _enumerate_operations(coordinates, symbols, tolerance)
    return _classify_finite(operations)


point_group = detect_point_group


def main(argv: Sequence[str] | None = None) -> int:
    """CLI entry point for ``pgmol``."""
    parser = argparse.ArgumentParser(
        prog="pgmol",
        description="Determine the Schoenflies point group of an XYZ structure.",
    )
    parser.add_argument("xyz_file", type=pathlib.Path, help="Path to an XYZ file")
    parser.add_argument(
        "--tol",
        type=float,
        default=1.0e-2,
        help="Cartesian matching tolerance in ångströms (default: 1e-2)",
    )
    arguments = parser.parse_args(argv)
    print(detect_point_group(arguments.xyz_file, arguments.tol))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import sys
import pathlib
import argparse
import numpy as np
from collections import defaultdict

def rotation_matrix(axis, theta):
    """Return the rotation matrix for rotation around axis by theta."""
    axis = axis / np.linalg.norm(axis)
    a = np.cos(theta / 2.0)
    b, c, d = -axis * np.sin(theta / 2.0)
    aa, bb, cc, dd = a * a, b * b, c * c, d * d
    bc, ad, ac, ab, bd, cd = b * c, a * d, a * c, a * b, b * d, c * d
    return np.array([
        [aa + bb - cc - dd, 2 * (bc + ad), 2 * (bd - ac)],
        [2 * (bc - ad), aa + cc - bb - dd, 2 * (cd + ab)],
        [2 * (bd + ac), 2 * (cd - ab), aa + dd - bb - cc]
    ])

def reflection_matrix(normal):
    """Return the reflection matrix across the plane perpendicular to normal."""
    n = normal / np.linalg.norm(normal)
    return np.eye(3) - 2 * np.outer(n, n)

def is_sym_op(coords_dict, R, tol):
    """Check if the rotation/reflection R is a symmetry operation."""
    for elem, coords in coords_dict.items():
        if len(coords) == 0:
            continue
        transformed = coords @ R.T
        diff = transformed[:, None, :] - coords[None, :, :]
        dist2 = np.sum(diff**2, axis=-1)
        min_dist2 = np.min(dist2, axis=1)
        if np.max(min_dist2) > tol**2:
            return False
    return True

def get_candidate_axes(coords):
    """Generate potential symmetry axes from coordinates."""
    axes = []

    # Principal axes of inertia
    I = coords.T @ coords
    eigvals, eigvecs = np.linalg.eigh(I)
    axes.extend([eigvecs[:, 0], eigvecs[:, 1], eigvecs[:, 2]])

    norms = np.linalg.norm(coords, axis=1)
    valid = norms > 1e-3
    valid_coords = coords[valid]

    # Vectors to atoms
    if len(valid_coords) > 0:
        axes.extend(valid_coords / norms[valid, None])

    # Midpoints and cross products between pairs
    n_valid = len(valid_coords)
    for i in range(n_valid):
        for j in range(i + 1, n_valid):
            v1 = valid_coords[i]
            v2 = valid_coords[j]
            midpoint = (v1 + v2) / 2
            norm_mid = np.linalg.norm(midpoint)
            if norm_mid > 1e-3:
                axes.append(midpoint / norm_mid)
            cross = np.cross(v1, v2)
            norm_cross = np.linalg.norm(cross)
            if norm_cross > 1e-3:
                axes.append(cross / norm_cross)

    # Deduplicate
    unique_axes = []
    for ax in axes:
        ax = ax / np.linalg.norm(ax)
        is_dup = False
        for u in unique_axes:
            if abs(np.dot(ax, u)) > 1 - 1e-4:
                is_dup = True
                break
        if not is_dup:
            unique_axes.append(ax)

    return unique_axes

def detect_point_group(xyz_input: str | pathlib.Path, tol: float = 1e-2) -> str:
    """
    Determine the Schoenflies point group of a molecule.
    """
    if isinstance(xyz_input, pathlib.Path):
        content = xyz_input.read_text().strip().split('\n')
    else:
        try:
            if pathlib.Path(xyz_input).is_file():
                content = pathlib.Path(xyz_input).read_text().strip().split('\n')
            else:
                content = xyz_input.strip().split('\n')
        except OSError:
            content = xyz_input.strip().split('\n')

    # Parse coordinates
    N = int(content[0].strip())
    coords_dict = defaultdict(list)
    all_coords = []
    masses = []

    # Simple mass map for center of mass approximation
    for line in content[2:N+2]:
        parts = line.split()
        if len(parts) >= 4:
            elem = parts[0]
            x, y, z = map(float, parts[1:4])
            coords_dict[elem].append([x, y, z])
            all_coords.append([x, y, z])
            # Arbitrary weighting: uniform per atom works just as well for symmetry
            masses.append(1.0) 

    if N == 1:
        return 'Kh'

    # Numpy arrays
    for k in coords_dict:
        coords_dict[k] = np.array(coords_dict[k])
    all_coords = np.array(all_coords)
    masses = np.array(masses)

    # Center to center of mass
    com = np.average(all_coords, axis=0, weights=masses)
    for k in coords_dict:
        coords_dict[k] -= com
    all_coords -= com

    # Check for linear
    is_linear = False
    ref_vec = None
    for pt in all_coords:
        if np.linalg.norm(pt) > 1e-3:
            if ref_vec is None:
                ref_vec = pt / np.linalg.norm(pt)
            else:
                if np.linalg.norm(np.cross(pt, ref_vec)) > tol:
                    break
    else:
        is_linear = True

    inversion_sym = is_sym_op(coords_dict, -np.eye(3), tol)
    if is_linear:
        return 'Dinfh' if inversion_sym else 'Cinfv'

    # Candidate axes
    candidate_axes = get_candidate_axes(all_coords)

    cn_axes = defaultdict(list)
    for ax in candidate_axes:
        for n in [8, 7, 6, 5, 4, 3, 2]:
            theta = 2 * np.pi / n
            R = rotation_matrix(ax, theta)
            if is_sym_op(coords_dict, R, tol):
                cn_axes[n].append(ax)
                break 

    n_max = max(cn_axes.keys()) if cn_axes else 1

    # Polyhedral / Cubic
    if n_max >= 3 and len(cn_axes[n_max]) > 1:
        # Icosahedral
        if n_max == 5:
            return 'Ih' if inversion_sym else 'I'
        # Octahedral
        elif n_max == 4:
            return 'Oh' if inversion_sym else 'O'
        # Tetrahedral
        else:
            if inversion_sym:
                return 'Th'
            # Check for S4
            s4_found = False
            for ax in candidate_axes:
                S4 = reflection_matrix(ax) @ rotation_matrix(ax, 2 * np.pi / 4)
                if is_sym_op(coords_dict, S4, tol):
                    s4_found = True
                    break
            if s4_found:
                return 'Td'
            return 'T'

    # Find principal axis
    if n_max > 1:
        principal_axis = cn_axes[n_max][0]
    else:
        principal_axis = np.array([0, 0, 1]) # Arbitrary

    # Check for perpendicular C2 axes
    has_perp_C2 = False
    if n_max > 1:
        for ax in cn_axes.get(2, []):
            if abs(np.dot(ax, principal_axis)) < 1e-3:
                has_perp_C2 = True
                break

    sigma_h_sym = is_sym_op(coords_dict, reflection_matrix(principal_axis), tol) if n_max > 1 else False

    if n_max > 1:
        if has_perp_C2:
            if sigma_h_sym:
                return f'D{n_max}h'
            # Check for sigma_d
            sigma_d = False
            for ax in candidate_axes:
                if abs(np.dot(ax, principal_axis)) < 1e-3:
                    if is_sym_op(coords_dict, reflection_matrix(ax), tol):
                        sigma_d = True
                        break
            return f'D{n_max}d' if sigma_d else f'D{n_max}'
        else:
            if sigma_h_sym:
                return f'C{n_max}h'
            # Check for sigma_v
            sigma_v = False
            for ax in candidate_axes:
                if abs(np.dot(ax, principal_axis)) < 1e-3:
                    if is_sym_op(coords_dict, reflection_matrix(ax), tol):
                        sigma_v = True
                        break
            if sigma_v:
                return f'C{n_max}v'
            # Check for S_2n
            s2n_found = False
            if n_max % 2 == 0 or n_max == 1:
                pass # usually handled
            S_2n_mat = reflection_matrix(principal_axis) @ rotation_matrix(principal_axis, 2 * np.pi / (2 * n_max))
            if is_sym_op(coords_dict, S_2n_mat, tol):
                return f'S{2 * n_max}'
            return f'C{n_max}'
    else:
        if inversion_sym:
            return 'Ci'
        # Check for any reflection plane
        has_sigma = False
        for ax in candidate_axes:
            if is_sym_op(coords_dict, reflection_matrix(ax), tol):
                has_sigma = True
                break
        return 'Cs' if has_sigma else 'C1'

point_group = detect_point_group

