def _read_xyz(source: str | Path) -> tuple[list[str], np.ndarray]:
    if isinstance(source, Path):
        text = source.read_text(encoding="utf-8")
    else:
        text = str(source)
        if "\n" not in text and "\r" not in text:
            path = Path(text)
            if path.exists():
                text = path.read_text(encoding="utf-8")

    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if len(lines) < 2:
        raise ValueError("Invalid XYZ input")

    try:
        n = int(lines[0].split()[0])
    except Exception as exc:
        raise ValueError("The first XYZ line must contain the atom count") from exc

    if n < 1 or len(lines) < n + 2:
        raise ValueError("XYZ input contains fewer atoms than declared")

    symbols: list[str] = []
    coords: list[list[float]] = []
    for line in lines[2 : n + 2]:
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(f"Invalid XYZ atom line: {line!r}")
        symbols.append(fields[0])
        coords.append([float(fields[1]), float(fields[2]), float(fields[3])])

    return symbols, np.asarray(coords, dtype=float)


def _canonical_matrix(matrix: np.ndarray) -> tuple[float, ...]:
    return tuple(np.round(matrix, 8).ravel())


def _independent_basis(vectors: np.ndarray, tol: float) -> tuple[int, ...]:
    nonzero = [i for i, v in enumerate(vectors) if np.linalg.norm(v) > tol]
    if len(nonzero) < 2:
        return tuple(nonzero[:1])

    best_pair = None
    best_area = -1.0
    for a in range(len(nonzero)):
        for b in range(a + 1, len(nonzero)):
            i, j = nonzero[a], nonzero[b]
            area = np.linalg.norm(np.cross(vectors[i], vectors[j]))
            if area > best_area:
                best_area = area
                best_pair = (i, j)

    scale = max(np.linalg.norm(v) for v in vectors) or 1.0
    if best_pair is None or best_area <= tol * scale:
        return (nonzero[0],)

    i, j = best_pair
    best_triple = None
    best_volume = -1.0
    for k in nonzero:
        volume = abs(np.dot(vectors[i], np.cross(vectors[j], vectors[k])))
        if volume > best_volume:
            best_volume = volume
            best_triple = k

    if best_triple is not None and best_volume > tol * scale**3:
        return (i, j, best_triple)
    return (i, j)


def _is_symmetry(
    matrix: np.ndarray,
    vectors: np.ndarray,
    symbols: list[str],
    buckets: dict[str, list[int]],
    tol: float,
) -> bool:
    transformed = vectors @ matrix.T
    tol2 = tol * tol
    for i, point in enumerate(transformed):
        found = False
        for j in buckets[symbols[i]]:
            if np.sum((point - vectors[j]) ** 2) <= tol2:
                found = True
                break
        if not found:
            return False
    return True


def _generate_operations(
    vectors: np.ndarray,
    symbols: list[str],
    tol: float,
) -> list[np.ndarray]:
    n = len(vectors)
    buckets: dict[str, list[int]] = {}
    for i, symbol in enumerate(symbols):
        buckets.setdefault(symbol, []).append(i)

    basis = _independent_basis(vectors, tol)
    if not basis:
        return [np.eye(3)]

    operations: dict[tuple[float, ...], np.ndarray] = {}

    if len(basis) == 1:
        # This case is handled as linear by the caller.  Include the obvious
        # axial operations needed for inversion testing.
        operations[_canonical_matrix(np.eye(3))] = np.eye(3)
        operations[_canonical_matrix(-np.eye(3))] = -np.eye(3)
        return list(operations.values())

    source = vectors[list(basis)].T
    source_rank = np.linalg.matrix_rank(source, tol=tol)
    target_lists = [buckets[symbols[i]] for i in basis]

    if len(basis) == 3 and source_rank == 3:
        source_inv = np.linalg.inv(source)
        for i in target_lists[0]:
            for j in target_lists[1]:
                for k in target_lists[2]:
                    target = vectors[[i, j, k]].T
                    matrix = target @ source_inv
                    if not np.allclose(matrix.T @ matrix, np.eye(3), atol=5 * tol):
                        continue
                    if _is_symmetry(matrix, vectors, symbols, buckets, tol):
                        operations[_canonical_matrix(matrix)] = matrix
    else:
        i0, i1 = basis[:2]
        a = vectors[i0]
        b = vectors[i1]
        ea = a / np.linalg.norm(a)
        bb = b - np.dot(b, ea) * ea
        eb = bb / np.linalg.norm(bb)
        en = np.cross(ea, eb)
        source_frame = np.column_stack((ea, eb, en))

        for j0 in target_lists[0]:
            for j1 in target_lists[1]:
                c = vectors[j0]
                d = vectors[j1]
                ec = c / np.linalg.norm(c)
                dd = d - np.dot(d, ec) * ec
                if np.linalg.norm(dd) <= tol:
                    continue
                ed = dd / np.linalg.norm(dd)
                ef = np.cross(ec, ed)
                target_frame = np.column_stack((ec, ed, ef))
                for sign in (1.0, -1.0):
                    matrix = (
                        target_frame
                        @ np.diag([1.0, 1.0, sign])
                        @ source_frame.T
                    )
                    if _is_symmetry(matrix, vectors, symbols, buckets, tol):
                        operations[_canonical_matrix(matrix)] = matrix

    if not operations:
        operations[_canonical_matrix(np.eye(3))] = np.eye(3)
    return list(operations.values())


def _proper_operations(operations: Iterable[np.ndarray]) -> list[np.ndarray]:
    return [m for m in operations if np.linalg.det(m) > 0.0]


def _matrix_order(matrix: np.ndarray, limit: int = 120) -> int:
    power = np.eye(3)
    for order in range(1, limit + 1):
        power = power @ matrix
        if np.allclose(power, np.eye(3), atol=2e-5):
            return order
    return limit


def _rotation_axis(matrix: np.ndarray) -> np.ndarray | None:
    vals, vecs = np.linalg.eig(matrix)
    candidates = [vecs[:, i].real for i, value in enumerate(vals) if abs(value - 1) < 1e-5]
    if not candidates:
        return None
    axis = candidates[0]
    norm = np.linalg.norm(axis)
    return axis / norm if norm else None


def _distinct_axes(operations: Iterable[np.ndarray]) -> list[np.ndarray]:
    axes: list[np.ndarray] = []
    for matrix in operations:
        if abs(np.trace(matrix) + 1.0) < 2e-5:
            axis = _rotation_axis(matrix)
            if axis is None:
                continue
            if not any(abs(np.dot(axis, other)) > 1 - 1e-4 for other in axes):
                axes.append(axis)
    return axes


def _classify(
    operations: list[np.ndarray],
    proper: list[np.ndarray],
    vectors: np.ndarray,
    tol: float,
) -> str:
    total = len(operations)
    pcount = len(proper)

    if len(vectors) == 1:
        return "Kh"

    scale = max(float(np.max(np.linalg.norm(vectors, axis=1))), 1.0)
    rank = np.linalg.matrix_rank(vectors, tol=max(tol, 1e-7) * scale)

    if rank <= 1:
        has_inversion = any(np.allclose(m, -np.eye(3), atol=5 * tol) for m in operations)
        return "Dinfh" if has_inversion else "Cinfv"

    proper_nonidentity = [
        m for m in proper if not np.allclose(m, np.eye(3), atol=5 * tol)
    ]
    orders = [_matrix_order(m) for m in proper_nonidentity]
    max_order = max(orders, default=1)

    # Polyhedral rotational subgroups.
    if pcount == 12:
        if total == 12:
            return "T"
        if any(np.allclose(m, -np.eye(3), atol=5 * tol) for m in operations):
            return "Th"
        return "Td"
    if pcount == 24:
        return "O" if total == 24 else "Oh"
    if pcount == 60:
        return "I" if total == 60 else "Ih"

    # Determine whether the proper subgroup is Cn or Dn.
    c2_axes = _distinct_axes(
        m for m in proper_nonidentity if _matrix_order(m) == 2
    )
    is_dihedral = pcount > 2 and (
        pcount == 2 * max_order or len(c2_axes) >= 3
    )

    principal = None
    if proper_nonidentity:
        candidates = [
            m for m in proper_nonidentity if _matrix_order(m) == max_order
        ]
        principal = _rotation_axis(candidates[0]) if candidates else None

    def is_reflection(m: np.ndarray) -> bool:
        return np.linalg.det(m) < 0 and np.allclose(m @ m, np.eye(3), atol=5 * tol)

    inversion = any(np.allclose(m, -np.eye(3), atol=5 * tol) for m in operations)
    reflections = [m for m in operations if is_reflection(m)]

    if not is_dihedral:
        n = max_order
        if pcount == 1:
            if total == 1:
                return "C1"
            if inversion:
                return "Ci"
            return "Cs"

        if total == n:
            return f"C{n}"

        if principal is not None:
            vertical = []
            horizontal = []
            for m in reflections:
                image = m @ principal
                if np.dot(image, principal) > 1 - 1e-4:
                    vertical.append(m)
                elif np.dot(image, principal) < -1 + 1e-4:
                    horizontal.append(m)
            if vertical:
                return f"C{n}v"
            if horizontal:
                return f"C{n}h"

        # Remaining cyclic groups are roto-reflection groups S_n.
        if n == 1:
            return "Cs" if reflections else "Ci"
        return f"S{2 * n}"

    n = max_order
    if total == pcount:
        return f"D{n}"

    horizontal = False
    if principal is not None:
        for m in reflections:
            if np.dot(m @ principal, principal) < -1 + 1e-4:
                horizontal = True
                break

    return f"D{n}h" if horizontal else f"D{n}d"


def detect_point_group(xyz_input: str | Path, tol: float = 1e-2) -> str:
    """Determine the Schoenflies point group of an XYZ molecule."""
    if tol <= 0:
        raise ValueError("tol must be positive")

    symbols, coordinates = _read_xyz(xyz_input)
    if len(symbols) == 1:
        return "Kh"

    masses = np.asarray([_MASSES.get(s, 1.0) for s in symbols], dtype=float)
    center = np.sum(coordinates * masses[:, None], axis=0) / np.sum(masses)
    vectors = coordinates - center

    operations = _generate_operations(vectors, symbols, tol)
    return _classify(operations, _proper_operations(operations), vectors, tol)


point_group = detect_point_group


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="pgmol",
        description="Determine the Schoenflies point group of an XYZ molecule.",
    )
    parser.add_argument("xyz_file", help="Path to an XYZ file")
    parser.add_argument(
        "--tol",
        type=float,
        default=1e-2,
        help="Cartesian coordinate tolerance in angstroms",
    )
    args = parser.parse_args(argv)

    try:
        print(detect_point_group(Path(args.xyz_file), tol=args.tol))
    except Exception as exc:
        parser.error(str(exc))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""
pgmol - Schoenflies point-group detection from XYZ coordinates.
Only depends on NumPy and the Python standard library.
"""
from __future__ import annotations

import pathlib
import sys
import argparse
import numpy as np

__all__ = ["detect_point_group", "point_group", "main"]

# ----------------------------------------------------------------------
# Internal helpers
# ----------------------------------------------------------------------

def _parse_input(xyz_input: str | pathlib.Path) -> tuple[list[str], np.ndarray]:
    """Parse raw XYZ text or file path into (symbols, Nx3 array)."""
    path = pathlib.Path(str(xyz_input))
    if path.is_file():
        text = path.read_text()
    else:
        text = str(xyz_input)

    lines = text.splitlines()
    idx = 0
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    if idx >= len(lines):
        raise ValueError("XYZ input is empty")
    try:
        n_atoms = int(lines[idx].strip())
    except Exception as exc:
        raise ValueError("First line must be number of atoms") from exc

    symbols: list[str] = []
    coords: list[list[float]] = []
    # Comment line is at idx+1; data starts at idx+2
    for line in lines[idx + 2:]:
        if len(symbols) >= n_atoms:
            break
        line = line.strip()
        if line == "":
            continue
        parts = line.split()
        if len(parts) < 4:
            continue
        symbols.append(parts[0])
        coords.append([float(parts[1]), float(parts[2]), float(parts[3])])
    if len(symbols) == 0:
        raise ValueError("No atomic coordinates found")
    return symbols, np.array(coords, dtype=float)


def _is_symmetry(p: np.ndarray, elements: list[str], R: np.ndarray, t: np.ndarray, tol: float) -> bool:
    """True iff R @ p[i] + t matches p[j] for all i with same element (permutation)."""
    # Centered or not - works with arbitrary t.
    p_trans = (R @ p.T).T + t
    n = len(elements)
    match_r = [-1] * n  # target -> source

    def dfs(u: int, seen: list[bool]) -> bool:
        for v in range(n):
            if elements[v] != elements[u]:
                continue
            if seen[v]:
                continue
            if np.linalg.norm(p_trans[u] - p[v]) < tol:
                seen[v] = True
                if match_r[v] == -1 or dfs(match_r[v], seen):
                    match_r[v] = u
                    return True
        return False

    for u in range(n):
        seen = [False] * n
        if not dfs(u, seen):
            return False
    return True


def _find_symmetries(p: np.ndarray, elements: list[str], tol: float = 1e-2) -> list[tuple[np.ndarray, np.ndarray]]:
    """Brute-force search for discrete orthogonal symmetries (R, t)."""
    p = np.array(p, dtype=float)
    p = p - p.mean(axis=0)
    ops: list[tuple[np.ndarray, np.ndarray]] = [(np.eye(3, dtype=float), np.zeros(3, dtype=float))]
    n = len(elements)
    if n <= 1:
        return ops

    # Find a non-collinear reference triple
    refs = None
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                v1 = p[j] - p[i]
                v2 = p[k] - p[i]
                if np.linalg.norm(np.cross(v1, v2)) > 1e-4:
                    refs = (i, j, k)
                    break
            if refs is not None:
                break
        if refs is not None:
            break

    if refs is None:
        # Essentially linear / very small; discrete search will not find non-identity ops
        # reliably via triple method. Return identity only; linear classification
        # relies on geometry check.
        return ops

    i0, i1, i2 = refs
    d01 = float(np.linalg.norm(p[i1] - p[i0]))
    d02 = float(np.linalg.norm(p[i2] - p[i0]))
    d12 = float(np.linalg.norm(p[i2] - p[i1]))

    for j0 in range(n):
        if elements[j0] != elements[i0]:
            continue
        for j1 in range(n):
            if elements[j1] != elements[i1]:
                continue
            if abs(np.linalg.norm(p[j1] - p[j0]) - d01) > tol:
                continue
            for j2 in range(n):
                if elements[j2] != elements[i2]:
                    continue
                if abs(np.linalg.norm(p[j2] - p[j0]) - d02) > tol:
                    continue
                if abs(np.linalg.norm(p[j2] - p[j1]) - d12) > tol:
                    continue

                a = p[i0]
                b = p[i1]
                c = p[i2]
                a_ = p[j0]
                b_ = p[j1]
                c_ = p[j2]

                u1 = b - a
                u2 = c - a
                u3 = np.cross(u1, u2)

                v1 = b_ - a_
                v2 = c_ - a_

                for det_sign in (1, -1):
                    v3 = det_sign * np.cross(v1, v2)
                    U = np.column_stack((u1, u2, u3))
                    if abs(np.linalg.det(U)) < 1e-6:
                        continue
                    M = np.column_stack((v1, v2, v3))
                    try:
                        R = M @ np.linalg.inv(U)
                    except np.linalg.LinAlgError:
                        continue
                    if np.linalg.norm(R.T @ R - np.eye(3)) > 1e-2:
                        continue
                    det_R = float(np.linalg.det(R))
                    if abs(det_R - det_sign) > 0.2:
                        continue
                    t = a_ - R @ a
                    if _is_symmetry(p, elements, R, t, tol):
                        # deduplicate
                        is_new = True
                        for R_old, t_old in ops:
                            if np.linalg.norm(R - R_old) < 1e-2 and np.linalg.norm(t - t_old) < 1e-2:
                                is_new = False
                                break
                        if is_new:
                            ops.append((R.copy(), t.copy()))
    return ops


def _classify(op_list: list[tuple[np.ndarray, np.ndarray]],
               p_raw: np.ndarray,
               elements: list[str],
               tol: float = 1e-2) -> str:
    """Return Schoenflies symbol from discovered symmetry operations."""
    p = np.array(p_raw, dtype=float)
    p -= p.mean(axis=0)
    n = len(elements)

    # Single atom
    if n == 1:
        return "Kh"

    # Linear geometry detection (all atoms essentially on a line)
    cov = np.cov(p.T) if n > 1 else np.eye(3) * 1e-6
    try:
        eigvals = np.sort(np.linalg.eigvalsh(cov))
    except Exception:
        eigvals = np.zeros(3)
    linear_geo = (eigvals[-2] < 1e-3) and (eigvals[-3] < 1e-3)

    # For linear molecules the only discrete groups are Dinfh / Cinfv.
    # Inversion check from operations
    inv_op = False
    for R, t in op_list:
        if np.linalg.norm(R + np.eye(3)) < 1e-2 and np.linalg.norm(t) < tol * 3:
            inv_op = True
            break
    if linear_geo or n == 2:
        return "Dinfh" if inv_op else "Cinfv"

    # Extract unique rotation matrices (ignore small translations)
    unique_R: list[np.ndarray] = []
    for R, t in op_list:
        if np.linalg.norm(t) > tol * 5:
            # For centered geometries true symmetries have t~0.
            pass
        is_new = True
        for R2 in unique_R:
            if np.linalg.norm(R - R2) < 1e-2:
                is_new = False
                break
        if is_new:
            unique_R.append(R.copy())

    # Inversion presence
    inv_present = any(np.linalg.norm(R + np.eye(3)) < 1e-2 for R in unique_R)

    # Count rotation axes (det=+1, not identity)
    axes: dict[int, list[np.ndarray]] = {}
    for R in unique_R:
        det = float(np.linalg.det(R))
        if abs(det - 1) > 0.3:
            continue
        tr = float(np.trace(R))
        if abs(tr - 3) < 0.3:
            continue  # identity
        ang = float(np.arccos(np.clip((tr - 1) / 2, -1.0, 1.0)))
        if ang < 1e-3:
            continue
        n_est = max(2, int(round(2 * np.pi / ang)) if ang > 1e-2 else 2)
        # Verify angle matches expected
        if abs(ang - 2 * np.pi / n_est) > 0.3:
            # Try closest integer
            n_est = max(2, int(round(2 * np.pi / ang)))
            if abs(ang - 2 * np.pi / n_est) > 0.3:
                n_est = 2
        # Axis from nullspace of (R - I)
        M = R - np.eye(3)
        _, _, Vt = np.linalg.svd(M)
        axis = Vt[-1, :]
        axis = axis / (np.linalg.norm(axis) + 1e-12)
        # Hemisphere normalization
        for i in range(3):
            if abs(axis[i]) > 1e-3:
                if axis[i] < 0:
                    axis = -axis
                break
        if n_est not in axes:
            axes[n_est] = []
        dup = False
        for a in axes[n_est]:
            if np.linalg.norm(axis - a) < 1e-2 or np.linalg.norm(axis + a) < 1e-2:
                dup = True
                break
        if not dup:
            axes[n_est].append(axis.copy())

    # ----- Polyhedral families -----
    # T family
    if (3 in axes and len(axes.get(3, [])) == 4 and
        2 in axes and len(axes.get(2, [])) == 3):
        if inv_present:
            return "Th"
        # Td has S4 operations (improper rotation, trace ~ -1, det=-1, axis along C2)
        s4 = False
        for R in unique_R:
            if abs(np.linalg.det(R) + 1) < 0.3:
                if abs(np.trace(R) + 1) < 0.6:
                    s4 = True
                    break
        if s4:
            return "Td"
        return "T"

    # O family
    if (4 in axes and len(axes.get(4, [])) == 3 and
        3 in axes and len(axes.get(3, [])) == 4):
        return "Oh" if inv_present else "O"

    # I family
    if (5 in axes and len(axes.get(5, [])) == 6 and
        3 in axes and len(axes.get(3, [])) == 10 and
        2 in axes and len(axes.get(2, [])) == 15):
        return "Ih" if inv_present else "I"

    # ----- Axial families -----
    # Principal axis = highest n found
    main_n = 0
    main_axis = None
    for k in sorted(axes.keys(), reverse=True):
        if k > main_n:
            main_n = k
            main_axis = axes[k][0] if axes[k] else None

    if main_n >= 2:
        # Horizontal mirror check (normal = principal axis)
        sigma_h = False
        for R in unique_R:
            det = float(np.linalg.det(R))
            if abs(det + 1) < 0.3 and abs(np.trace(R) - 1) < 0.5:
                M = R + np.eye(3)
                _, _, Vt = np.linalg.svd(M)
                normal = Vt[-1, :]
                normal /= np.linalg.norm(normal) + 1e-12
                if np.dot(normal, main_axis) < 0:
                    normal = -normal
                # Plane is perp to axis => normal aligns with axis
                if np.linalg.norm(np.abs(normal) - np.abs(main_axis)) < 0.25:
                    sigma_h = True

        # Perpendicular C2 axes
        c2_axes = axes.get(2, [])
        perp_c2 = sum(1 for a in c2_axes if abs(np.dot(a, main_axis)) < 0.25)
        c2_perp = (perp_c2 == main_n)

        if c2_perp:
            if sigma_h:
                return f"D{main_n}h"
            if inv_present:
                return f"D{main_n}d"
            return f"D{main_n}"
        else:
            if sigma_h:
                return f"C{main_n}h"
            # Count vertical planes (reflection, normal perp to axis)
            sigma_v = 0
            for R in unique_R:
                if abs(np.linalg.det(R) + 1) < 0.3 and abs(np.trace(R) - 1) < 0.5:
                    M = R + np.eye(3)
                    _, _, Vt = np.linalg.svd(M)
                    normal = Vt[-1, :]
                    normal /= np.linalg.norm(normal) + 1e-12
                    if abs(np.dot(normal, main_axis)) < 0.25:
                        sigma_v += 1
            if sigma_v >= main_n:
                return f"C{main_n}v"
            # Improper rotation Sn check
            sn = False
            for R in unique_R:
                if abs(np.linalg.det(R) + 1) < 0.3:
                    M = R + np.eye(3)
                    _, _, Vt = np.linalg.svd(M)
                    axis_s = Vt[-1, :]
                    axis_s /= np.linalg.norm(axis_s) + 1e-12
                    if abs(np.dot(axis_s, main_axis)) > 0.9:
                        tr = float(np.trace(R))
                        cos_th = (tr + 1) / 2
                        if -1 <= cos_th <= 1:
                            th = float(np.arccos(np.clip(cos_th, -1, 1)))
                            n_est = max(2, int(round(2 * np.pi / th)) if th > 1e-3 else 2)
                            if abs(th - 2 * np.pi / n_est) < 0.2 and n_est == main_n:
                                sn = True
                                break
            if sn:
                return f"S{main_n}"
            return f"C{main_n}"

    # No rotation axis
    refl = 0
    for R in unique_R:
        if abs(np.linalg.det(R) + 1) < 0.3 and abs(np.trace(R) - 1) < 0.5:
            refl += 1
    if inv_present:
        return "Ci" if refl == 0 else "Ci"  # with only identity+inv; if refl also -> still report Ci as closest standard
    if refl > 0:
        return "Cs"
    return "C1"


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------

def detect_point_group(xyz_input: str | pathlib.Path, tol: float = 1e-2) -> str:
    """
    Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input : str | pathlib.Path
        Path to an XYZ file OR a raw XYZ-formatted multiline string.
    tol : float, optional
        Cartesian distance tolerance in ångströms (default: 1e-2).

    Returns
    -------
    str
        Exact ASCII Schoenflies symbol.
    """
    symbols, coords = _parse_input(xyz_input)
    ops = _find_symmetries(coords, symbols, tol)
    return _classify(ops, coords, symbols, tol)


point_group = detect_point_group


