"""Coordinate-based molecular Schoenflies point-group detection.

Requires only NumPy and the Python standard library.

The module can also be run directly::

    python -m pgmol molecule.xyz
"""

from __future__ import annotations

import argparse
import math
import pathlib
from collections import defaultdict

import numpy as np

__all__ = ["detect_point_group", "point_group"]


def _read_xyz(xyz_input: str | pathlib.Path) -> tuple[list[str], np.ndarray]:
    if isinstance(xyz_input, pathlib.Path):
        text = xyz_input.read_text(encoding="utf-8")
    elif isinstance(xyz_input, str):
        if "\n" in xyz_input or "\r" in xyz_input:
            text = xyz_input
        else:
            try:
                path = pathlib.Path(xyz_input)
                text = path.read_text(encoding="utf-8") if path.is_file() else xyz_input
            except OSError:
                text = xyz_input
    else:
        raise TypeError("xyz_input must be a string or pathlib.Path")

    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("XYZ input must contain an atom count and a comment line")

    try:
        count = int(lines[0].strip())
    except ValueError as exc:
        raise ValueError("Invalid XYZ atom count") from exc

    if count < 1 or len(lines) < count + 2:
        raise ValueError("XYZ input has an invalid atom count or missing atom lines")

    symbols: list[str] = []
    coordinates: list[list[float]] = []
    for line in lines[2 : count + 2]:
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(f"Invalid XYZ atom line: {line!r}")
        symbols.append(fields[0].capitalize())
        try:
            coordinates.append([float(value) for value in fields[1:4]])
        except ValueError as exc:
            raise ValueError(f"Invalid XYZ coordinates: {line!r}") from exc

    points = np.asarray(coordinates, dtype=float)
    if not np.isfinite(points).all():
        raise ValueError("XYZ coordinates must be finite")
    return symbols, points


def _unit(vector: np.ndarray) -> np.ndarray | None:
    length = float(np.linalg.norm(vector))
    if length < 1e-12:
        return None
    return vector / length


def _candidate_axes(
    points: np.ndarray, symbols: list[str], tol: float
) -> list[np.ndarray]:
    """Construct rotation-axis candidates from intrinsic coordinate vectors.

    In particular, equal-length edges meeting at a vertex of a rotational
    orbit supply its axis even when the inertia tensor is spherical.
    """
    axes: dict[tuple[int, int, int], np.ndarray] = {}

    def add(vector: np.ndarray) -> None:
        axis = _unit(vector)
        if axis is None:
            return
        for component in axis:
            if abs(component) > 1e-10:
                if component < 0:
                    axis = -axis
                break
        key = tuple(int(round(float(value) * 1_000_000)) for value in axis)
        axes.setdefault(key, axis)

    count = len(points)
    radii = np.linalg.norm(points, axis=1)

    for point in points:
        add(point)

    # Principal inertia directions are useful candidates, but are never
    # treated as evidence that a symmetry actually exists.
    _, eigenvectors = np.linalg.eigh(points.T @ points)
    for column in eigenvectors.T:
        add(column)

    for i in range(count):
        for j in range(i + 1, count):
            add(np.cross(points[i], points[j]))
            if symbols[i] == symbols[j] and abs(radii[i] - radii[j]) <= 2 * tol:
                add(points[i] + points[j])

    for i in range(count):
        groups: dict[str, list[int]] = defaultdict(list)
        for j in range(count):
            if i != j and symbols[i] == symbols[j]:
                if abs(radii[i] - radii[j]) <= 2 * tol:
                    groups[symbols[j]].append(j)

        for members in groups.values():
            for position, j in enumerate(members):
                first = points[j] - points[i]
                first_length = float(np.linalg.norm(first))
                for k in members[position + 1 :]:
                    second = points[k] - points[i]
                    if abs(first_length - np.linalg.norm(second)) <= 2 * tol:
                        add(np.cross(first, second))

    return list(axes.values())


class _Symmetry:
    def __init__(self, symbols: list[str], points: np.ndarray, tol: float):
        self.points = points
        self.tol = tol
        self.groups: list[np.ndarray] = []
        by_symbol: dict[str, list[int]] = defaultdict(list)
        for index, symbol in enumerate(symbols):
            by_symbol[symbol].append(index)
        self.groups = [np.asarray(indices) for indices in by_symbol.values()]

    def accepts(self, matrix: np.ndarray) -> bool:
        transformed = self.points @ matrix.T
        threshold = self.tol * self.tol * (1 + 1e-10)

        for indices in self.groups:
            targets = self.points[indices]
            mapped = transformed[indices]
            distances = np.sum(
                (mapped[:, None, :] - targets[None, :, :]) ** 2, axis=2
            )
            choices = [np.flatnonzero(row <= threshold) for row in distances]
            if any(len(options) == 0 for options in choices):
                return False

            # A bijection is required: independently matching each atom to
            # its nearest neighbor could accept a false symmetry.
            assignment = [-1] * len(indices)

            def augment(source: int, visited: set[int]) -> bool:
                for target in choices[source]:
                    target = int(target)
                    if target in visited:
                        continue
                    visited.add(target)
                    previous = assignment[target]
                    if previous == -1 or augment(previous, visited):
                        assignment[target] = source
                        return True
                return False

            for source in sorted(range(len(indices)), key=lambda x: len(choices[x])):
                if not augment(source, set()):
                    return False

        return True


def _rotation(axis: np.ndarray, angle: float) -> np.ndarray:
    x, y, z = axis
    sine = math.sin(angle)
    cosine = math.cos(angle)
    cross = np.array([[0, -z, y], [z, 0, -x], [-y, x, 0]])
    return (
        cosine * np.eye(3)
        + (1 - cosine) * np.outer(axis, axis)
        + sine * cross
    )


def _max_possible_order(
    axis: np.ndarray, points: np.ndarray, symbols: list[str], tol: float
) -> int:
    """Upper-bound an axis order using atoms' heights and radial distances."""
    heights = points @ axis
    radial = np.linalg.norm(points - heights[:, None] * axis, axis=1)
    off_axis = np.flatnonzero(radial > tol)
    if len(off_axis) == 0:
        return 1

    largest = 1
    for i in off_axis:
        matching = sum(
            symbols[j] == symbols[i]
            and abs(heights[j] - heights[i]) <= 3 * tol
            and abs(radial[j] - radial[i]) <= 3 * tol
            for j in off_axis
        )
        largest = max(largest, matching)
    return largest


def _mirror_normals(
    points: np.ndarray, symbols: list[str], tol: float
) -> list[np.ndarray]:
    normals: dict[tuple[int, int, int], np.ndarray] = {}

    def add(vector: np.ndarray) -> None:
        normal = _unit(vector)
        if normal is None:
            return
        for component in normal:
            if abs(component) > 1e-10:
                if component < 0:
                    normal = -normal
                break
        key = tuple(int(round(float(value) * 1_000_000)) for value in normal)
        normals.setdefault(key, normal)

    radii = np.linalg.norm(points, axis=1)
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            # A mirror either fixes atoms in its plane or exchanges pairs.
            add(np.cross(points[i], points[j]))
            if symbols[i] == symbols[j] and abs(radii[i] - radii[j]) <= 2 * tol:
                add(points[i] - points[j])

    _, eigenvectors = np.linalg.eigh(points.T @ points)
    for normal in eigenvectors.T:
        add(normal)

    return list(normals.values())


def detect_point_group(xyz_input: str | pathlib.Path, tol: float = 1e-2) -> str:
    """Determine the ASCII Schoenflies point group from XYZ coordinates.

    ``xyz_input`` may be a file path or a raw multiline XYZ string. ``tol``
    is a Cartesian matching tolerance in ångströms.
    """
    if not math.isfinite(tol) or tol <= 0:
        raise ValueError("tol must be finite and positive")

    symbols, points = _read_xyz(xyz_input)
    if len(points) == 1:
        return "Kh"

    # The geometric centroid is fixed by every permutation of the atoms,
    # irrespective of their elements or masses.
    points = points - points.mean(axis=0)
    symmetry = _Symmetry(symbols, points, tol)
    inversion = symmetry.accepts(-np.eye(3))

    singular_values = np.linalg.svd(points, compute_uv=False)
    if singular_values[1] <= tol:
        return "Dinfh" if inversion else "Cinfv"

    axes = _candidate_axes(points, symbols, tol)
    rotations: list[tuple[np.ndarray, int]] = []

    for axis in axes:
        upper = min(len(points), _max_possible_order(axis, points, symbols, tol))
        for order in range(upper, 1, -1):
            if symmetry.accepts(_rotation(axis, 2 * math.pi / order)):
                rotations.append((axis, order))
                break

    highest = max((order for _, order in rotations), default=1)

    normals = _mirror_normals(points, symbols, tol)
    mirrors = [
        normal
        for normal in normals
        if symmetry.accepts(np.eye(3) - 2 * np.outer(normal, normal))
    ]

    if highest >= 5:
        return "Ih" if inversion else "I"

    if highest == 4:
        fourth_axes = [axis for axis, order in rotations if order == 4]
        if len(fourth_axes) >= 2:
            return "Oh" if inversion else "O"

    if highest >= 3:
        third_axes = [axis for axis, order in rotations if order % 3 == 0]
        if len(third_axes) >= 2:
            if inversion:
                return "Th"
            return "Td" if mirrors else "T"

    if highest == 1:
        if inversion:
            return "Ci"
        return "Cs" if mirrors else "C1"

    principal = next(axis for axis, order in rotations if order == highest)
    perpendicular_twos = [
        axis
        for axis, order in rotations
        if order % 2 == 0 and abs(float(np.dot(axis, principal))) < 1e-4
    ]
    dihedral = bool(perpendicular_twos)

    horizontal = any(
        abs(float(np.dot(normal, principal))) > 1 - 1e-4
        for normal in mirrors
    )
    vertical = any(
        abs(float(np.dot(normal, principal))) < 1e-4
        for normal in mirrors
    )

    if dihedral:
        if horizontal:
            return f"D{highest}h"
        if vertical:
            return f"D{highest}d"
        return f"D{highest}"

    if horizontal:
        return f"C{highest}h"
    if vertical:
        return f"C{highest}v"

    horizontal_reflection = np.eye(3) - 2 * np.outer(principal, principal)
    improper = _rotation(principal, math.pi / highest) @ horizontal_reflection
    if symmetry.accepts(improper):
        return f"S{2 * highest}"
    return f"C{highest}"


point_group = detect_point_group


def main() -> None:
    parser = argparse.ArgumentParser(description="Determine an XYZ molecule's point group")
    parser.add_argument("xyz_file", type=pathlib.Path)
    parser.add_argument(
        "--tol",
        type=float,
        default=1e-2,
        help="Cartesian matching tolerance in ångströms",
    )
    args = parser.parse_args()
    print(detect_point_group(args.xyz_file, tol=args.tol))


if __name__ == "__main__":
    main()

"""Determine molecular Schoenflies point groups from XYZ coordinates.

The implementation uses only the Python standard library and NumPy. Symmetry
operations are found by matching geometry-preserving atom mappings and
orthogonal transformations; element symbols are preserved in every match.
"""

from __future__ import annotations

import argparse
import itertools
import math
import pathlib
from typing import Iterable

import numpy as np


__all__ = ["detect_point_group", "point_group"]


def _read_xyz(xyz_input: str | pathlib.Path) -> tuple[list[str], np.ndarray]:
    if isinstance(xyz_input, pathlib.Path):
        text = xyz_input.read_text(encoding="utf-8")
    elif isinstance(xyz_input, str):
        if "\n" in xyz_input or "\r" in xyz_input:
            text = xyz_input
        else:
            path = pathlib.Path(xyz_input)
            if not path.exists():
                raise FileNotFoundError(xyz_input)
            text = path.read_text(encoding="utf-8")
    else:
        raise TypeError("xyz_input must be a file path or raw XYZ string")

    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("XYZ input must contain an atom count and comment line")

    try:
        count = int(lines[0].strip())
    except ValueError as exc:
        raise ValueError("Invalid atom count in XYZ input") from exc
    if count < 1:
        raise ValueError("XYZ input must contain at least one atom")
    if len(lines) < count + 2:
        raise ValueError("XYZ input contains fewer atom rows than declared")

    elements: list[str] = []
    coords: list[list[float]] = []
    for line_number, line in enumerate(lines[2 : count + 2], start=3):
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(f"Invalid atom row on line {line_number}")
        elements.append(fields[0])
        try:
            coords.append([float(fields[1]), float(fields[2]), float(fields[3])])
        except ValueError as exc:
            raise ValueError(f"Invalid coordinates on line {line_number}") from exc

    xyz = np.asarray(coords, dtype=float)
    if not np.all(np.isfinite(xyz)):
        raise ValueError("XYZ coordinates must be finite")
    return elements, xyz


def _has_matching_permutation(
    transformed: np.ndarray,
    elements: list[str],
    tolerance: float,
) -> bool:
    """Test whether transformed atoms can be bijectively matched to the input."""
    n = len(elements)
    tolerance_sq = tolerance * tolerance
    adjacency: list[list[int]] = []

    for i in range(n):
        candidates = [
            j
            for j in range(n)
            if elements[i] == elements[j]
            and float(np.dot(transformed[i] - transformed[j],
                             transformed[i] - transformed[j]))
            <= tolerance_sq
        ]
        if not candidates:
            return False
        adjacency.append(candidates)

    # Assign the most constrained atoms first. This avoids the false negatives
    # that a simple nearest-neighbour greedy assignment can produce.
    order = sorted(range(n), key=lambda i: len(adjacency[i]))
    assigned_to = [-1] * n

    def augment(atom_index: int, seen: list[bool]) -> bool:
        for target in adjacency[atom_index]:
            if seen[target]:
                continue
            seen[target] = True
            if assigned_to[target] == -1 or augment(assigned_to[target], seen):
                assigned_to[target] = atom_index
                return True
        return False

    for atom_index in order:
        if not augment(atom_index, [False] * n):
            return False
    return True


def _orthogonalize(matrix: np.ndarray) -> np.ndarray:
    """Return the nearest orthogonal matrix to ``matrix``."""
    u, _, vt = np.linalg.svd(matrix)
    return u @ vt


def _add_operation(
    operations: list[np.ndarray],
    operation: np.ndarray,
    coords: np.ndarray,
    elements: list[str],
    tolerance: float,
) -> None:
    operation = _orthogonalize(operation)
    if not _has_matching_permutation(coords @ operation, elements, tolerance):
        return
    if not any(np.linalg.norm(operation - old, ord="fro") < 1.0e-5
               for old in operations):
        operations.append(operation)


def _best_rank_three_basis(coords: np.ndarray) -> tuple[int, int, int]:
    """Find a well-conditioned triple of atom position vectors."""
    n = len(coords)
    best_pair: tuple[int, int] | None = None
    best_area = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            area = float(np.linalg.norm(np.cross(coords[i], coords[j])))
            if area > best_area:
                best_area = area
                best_pair = (i, j)
    if best_pair is None or best_area == 0.0:
        raise ValueError("Could not find a rank-three coordinate basis")

    i, j = best_pair
    normal = np.cross(coords[i], coords[j])
    best_k = -1
    best_volume = 0.0
    for k in range(n):
        if k == i or k == j:
            continue
        volume = abs(float(np.dot(normal, coords[k])))
        if volume > best_volume:
            best_volume = volume
            best_k = k
    if best_k < 0 or best_volume == 0.0:
        raise ValueError("Could not find a rank-three coordinate basis")
    return i, j, best_k


def _enumerate_rank_three_operations(
    coords: np.ndarray,
    elements: list[str],
    tolerance: float,
) -> list[np.ndarray]:
    n = len(coords)
    basis_indices = _best_rank_three_basis(coords)
    source = coords[list(basis_indices)]
    gram = source @ source.T
    scale = max(float(np.max(np.linalg.norm(coords, axis=1))), 1.0)
    gram_tol = 4.0 * tolerance * scale + tolerance * tolerance

    candidates: list[list[int]] = []
    for source_index in basis_indices:
        candidates.append([
            j for j in range(n)
            if elements[j] == elements[source_index]
            and abs(float(np.dot(coords[j], coords[j]) - gram[
                len(candidates), len(candidates)
            ])) <= gram_tol
        ])

    operations: list[np.ndarray] = []
    for a in candidates[0]:
        va = coords[a]
        if abs(float(np.dot(va, va) - gram[0, 0])) > gram_tol:
            continue
        for b in candidates[1]:
            vb = coords[b]
            if abs(float(np.dot(va, vb) - gram[0, 1])) > gram_tol:
                continue
            if abs(float(np.dot(vb, vb) - gram[1, 1])) > gram_tol:
                continue
            for c in candidates[2]:
                vc = coords[c]
                if (
                    abs(float(np.dot(va, vc) - gram[0, 2])) > gram_tol
                    or abs(float(np.dot(vb, vc) - gram[1, 2])) > gram_tol
                    or abs(float(np.dot(vc, vc) - gram[2, 2])) > gram_tol
                ):
                    continue
                target = np.vstack((va, vb, vc))
                try:
                    row_transform = np.linalg.solve(source, target)
                except np.linalg.LinAlgError:
                    continue
                _add_operation(
                    operations, row_transform, coords, elements, tolerance
                )

    return operations


def _enumerate_rank_two_operations(
    coords: np.ndarray,
    elements: list[str],
    tolerance: float,
) -> list[np.ndarray]:
    n = len(coords)
    best_pair: tuple[int, int] | None = None
    best_area = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            area = float(np.linalg.norm(np.cross(coords[i], coords[j])))
            if area > best_area:
                best_area = area
                best_pair = (i, j)
    if best_pair is None:
        return [np.eye(3)]

    i, j = best_pair
    e1 = coords[i] / np.linalg.norm(coords[i])
    v = coords[j] - np.dot(coords[j], e1) * e1
    if np.linalg.norm(v) == 0.0:
        return [np.eye(3)]
    e2 = v / np.linalg.norm(v)
    normal = np.cross(e1, e2)
    basis = np.column_stack((e1, e2, normal))
    planar = coords @ basis[:, :2]

    source = planar[[i, j]]
    gram = source @ source.T
    scale = max(float(np.max(np.linalg.norm(coords, axis=1))), 1.0)
    gram_tol = 4.0 * tolerance * scale + tolerance * tolerance

    candidate_lists: list[list[int]] = []
    for source_index, diagonal in ((i, 0), (j, 1)):
        candidate_lists.append([
            k for k in range(n)
            if elements[k] == elements[source_index]
            and abs(float(np.dot(planar[k], planar[k]) - gram[diagonal, diagonal]))
            <= gram_tol
        ])

    operations: list[np.ndarray] = []
    for a in candidate_lists[0]:
        va = planar[a]
        for b in candidate_lists[1]:
            vb = planar[b]
            if (
                abs(float(np.dot(va, vb) - gram[0, 1])) > gram_tol
                or abs(float(np.dot(vb, vb) - gram[1, 1])) > gram_tol
            ):
                continue
            target = np.vstack((va, vb))
            try:
                transform_2d = _orthogonalize(np.linalg.solve(source, target))
            except np.linalg.LinAlgError:
                continue
            for normal_sign in (1.0, -1.0):
                local = np.eye(3)
                local[:2, :2] = transform_2d
                local[2, 2] = normal_sign
                operation = basis @ local @ basis.T
                _add_operation(
                    operations, operation, coords, elements, tolerance
                )
    return operations


def _rotation_order(operation: np.ndarray) -> int:
    """Return the order of a proper rotation matrix."""
    angle_cos = min(1.0, max(-1.0, (float(np.trace(operation)) - 1.0) / 2.0))
    angle = math.acos(angle_cos)
    if angle < 1.0e-5:
        return 1
    return max(2, int(round(2.0 * math.pi / angle)))


def _axis_of_rotation(operation: np.ndarray) -> np.ndarray | None:
    values, vectors = np.linalg.eig(operation.T)
    index = int(np.argmin(np.abs(values - 1.0)))
    vector = np.real(vectors[:, index])
    length = float(np.linalg.norm(vector))
    if length < 1.0e-8:
        return None
    return vector / length


def _is_mirror(operation: np.ndarray) -> bool:
    return float(np.linalg.det(operation)) < 0.0 and abs(
        float(np.trace(operation)) - 1.0
    ) < 1.0e-4


def _has_horizontal_mirror(
    operations: Iterable[np.ndarray],
    axis: np.ndarray | None,
) -> bool:
    if axis is None:
        return False
    for operation in operations:
        if not _is_mirror(operation):
            continue
        # A horizontal mirror reverses the principal axis.
        if np.linalg.norm(operation @ axis + axis) < 1.0e-4:
            return True
    return False


def _has_vertical_mirror(
    operations: Iterable[np.ndarray],
    axis: np.ndarray | None,
) -> bool:
    if axis is None:
        return False
    for operation in operations:
        if not _is_mirror(operation):
            continue
        # A vertical mirror leaves the principal axis in its plane.
        if np.linalg.norm(operation @ axis - axis) < 1.0e-4:
            return True
    return False


def _classify_operations(operations: list[np.ndarray]) -> str:
    proper = [
        operation for operation in operations
        if float(np.linalg.det(operation)) > 0.0
    ]
    improper = [
        operation for operation in operations
        if float(np.linalg.det(operation)) < 0.0
    ]
    proper_count = len(proper)
    total_count = len(operations)

    if proper_count == 0:
        return "C1"

    orders = [_rotation_order(operation) for operation in proper]
    max_order = max(orders)

    # The finite proper polyhedral rotation groups have characteristic orders.
    if proper_count == 12 and max_order == 3:
        if not improper:
            return "T"
        if any(np.linalg.norm(operation + np.eye(3), ord="fro") < 1.0e-4
               for operation in improper):
            return "Th"
        return "Td"
    if proper_count == 24 and max_order == 4:
        return "Oh" if improper else "O"
    if proper_count == 60 and max_order == 5:
        return "Ih" if improper else "I"

    # Determine whether the proper subgroup is cyclic or dihedral.
    cyclic_order = max_order
    is_cyclic = proper_count == cyclic_order
    is_dihedral = proper_count == 2 * cyclic_order

    if not is_cyclic and not is_dihedral:
        # This fallback is useful for degenerate numerical inputs; it avoids
        # mistaking a spherical moment tensor for a polyhedral symmetry group.
        is_cyclic = proper_count == 1
        is_dihedral = not is_cyclic and proper_count % 2 == 0

    # Select a highest-order axis. For D2 and similar groups all axes can be
    # equivalent; the classification below is independent of that choice.
    principal_axis = None
    for operation, order in zip(proper, orders):
        if order == max_order and order > 1:
            principal_axis = _axis_of_rotation(operation)
            if principal_axis is not None:
                break

    if not improper:
        if is_cyclic:
            return f"C{cyclic_order}"
        if is_dihedral:
            return f"D{cyclic_order}"
        return f"C{max(1, cyclic_order)}"

    has_horizontal = _has_horizontal_mirror(operations, principal_axis)
    has_vertical = _has_vertical_mirror(operations, principal_axis)

    if is_cyclic:
        if cyclic_order == 1:
            # With C1 as the proper subgroup, the only possible added operation
            # is inversion or a reflection.
            if any(np.linalg.norm(operation + np.eye(3), ord="fro") < 1.0e-4
                   for operation in improper):
                return "Ci"
            return "Cs"

        if has_horizontal and has_vertical:
            # This case occurs for the small, highly overlapping axial groups.
            return f"D{cyclic_order}h"
        if has_horizontal:
            return f"C{cyclic_order}h"
        if has_vertical:
            return f"C{cyclic_order}v"

        # A cyclic proper subgroup with an improper coset and no mirror planes
        # is an improper-rotation group S_(2n).
        if total_count == 2 * cyclic_order:
            return f"S{2 * cyclic_order}"
        return f"C{cyclic_order}"

    if is_dihedral:
        if has_horizontal:
            return f"D{cyclic_order}h"
        if has_vertical:
            return f"D{cyclic_order}d"
        # In the usual Schoenflies families a dihedral improper extension has
        # either horizontal or diagonal/vertical mirror planes.
        if total_count == 4 * cyclic_order:
            return f"D{cyclic_order}d"
        return f"D{cyclic_order}"

    return "C1"


def detect_point_group(
    xyz_input: str | pathlib.Path,
    tol: float = 1e-2,
) -> str:
    """Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input:
        Path to an XYZ file or a raw multiline XYZ-formatted string.
    tol:
        Cartesian distance tolerance in ångströms.

    Returns
    -------
    str
        Schoenflies point group symbol.
    """
    if not math.isfinite(tol) or tol <= 0.0:
        raise ValueError("tol must be a positive finite distance")

    elements, xyz = _read_xyz(xyz_input)
    if len(elements) == 1:
        return "Kh"

    # Translation invariance: all symmetry operations are tested about the
    # geometric centre, not about the input coordinate origin.
    coords = xyz - np.mean(xyz, axis=0)
    singular_values = np.linalg.svd(coords, compute_uv=False)
    rank = int(np.count_nonzero(singular_values > tol))

    if rank == 0:
        return "Kh"

    if rank == 1:
        if _has_matching_permutation(-coords, elements, tol):
            return "Dinfh"
        return "Cinfv"

    if rank == 2:
        operations = _enumerate_rank_two_operations(coords, elements, tol)
    else:
        operations = _enumerate_rank_three_operations(coords, elements, tol)

    # The identity should always be present, including in borderline cases.
    _add_operation(operations, np.eye(3), coords, elements, tol)
    return _classify_operations(operations)


point_group = detect_point_group


def main(argv: list[str] | None = None) -> int:
    """Command-line entry point for ``pgmol``."""
    parser = argparse.ArgumentParser(
        description="Determine a molecule's Schoenflies point group from XYZ."
    )
    parser.add_argument("xyz_file", help="path to an XYZ file")
    parser.add_argument(
        "--tol",
        type=float,
        default=1e-2,
        help="Cartesian matching tolerance in angstroms (default: 0.01)",
    )
    args = parser.parse_args(argv)
    print(detect_point_group(args.xyz_file, tol=args.tol))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import numpy as np
import pathlib
from typing import Union

def detect_point_group(xyz_input: Union[str, pathlib.Path], tol: float = 1e-2) -> str:
    """
    Determine the Schoenflies point group of a molecule.

    Parameters
    ----------
    xyz_input : str | pathlib.Path
        Path to an XYZ file OR a raw XYZ-formatted multiline string.
    tol : float, optional
        Cartesian distance tolerance in ångströms (default: 1e-2).

    Returns
    -------
    str
        Exact ASCII Schoenflies symbol.
    """
    # Load XYZ coordinates
    if isinstance(xyz_input, pathlib.Path) or (isinstance(xyz_input, str) and pathlib.Path(xyz_input).exists()):
        with open(xyz_input, 'r') as f:
            xyz_string = f.read()
    else:
        xyz_string = xyz_input

    lines = xyz_string.strip().splitlines()
    natoms = int(lines[0])
    coords = []
    elements = []
    for line in lines[2:]:
        parts = line.split()
        elements.append(parts[0])
        coords.append([float(x) for x in parts[1:]])
    coords = np.array(coords)

    # Center coordinates
    centroid = np.mean(coords, axis=0)
    coords -= centroid

    # Compute inertia tensor and diagonalize
    inertia_tensor = np.zeros((3, 3))
    for i, atom in enumerate(coords):
        mass = get_atomic_mass(elements[i])
        inertia_tensor += mass * (np.dot(atom, atom) * np.eye(3) - np.outer(atom, atom))
    eigenvalues, eigenvectors = np.linalg.eigh(inertia_tensor)

    # Sort eigenvalues and eigenvectors
    idx = np.argsort(eigenvalues)
    eigenvalues = eigenvalues[idx]
    eigenvectors = eigenvectors[:, idx]

    # Transform coordinates to principal axes
    coords = np.dot(coords, eigenvectors)

    # Detect point group
    pg = detect_point_group_from_coords(coords, elements, tol)

    return pg

def get_atomic_mass(element: str) -> float:
    # Simplified atomic masses for demonstration; use a more comprehensive source in production
    masses = {
        'H': 1.00794, 'He': 4.002602, 'Li': 6.941, 'Be': 9.012182, 'B': 10.811, 'C': 12.0107,
        'N': 14.0067, 'O': 15.9994, 'F': 18.9984032, 'Ne': 20.1797
    }
    return masses.get(element, 12.0)  # Default to carbon for unknown elements

def detect_point_group_from_coords(coords: np.ndarray, elements: list, tol: float) -> str:
    # Check for single atom
    if len(elements) == 1:
        return 'Kh'

    # Check for linear molecule
    if is_linear(coords, tol):
        return 'Dinfh' if has_inversion_center(coords, elements, tol) else 'Cinfv'

    # Detect rotational symmetry
    n_max = 6  # Check up to C6
    max_n = 1
    for n in range(2, n_max + 1):
        if has_c_n_axis(coords, n, tol):
            max_n = n

    # Check for polyhedral groups
    if max_n >= 3:
        if has_tetrahedral_symmetry(coords, elements, tol):
            return 'Td' if has_c3_axes(coords, tol) and has_c2_axes(coords, tol) and has_s4_axes(coords, tol) else 'T'
        elif has_octahedral_symmetry(coords, elements, tol):
            return 'Oh'
        elif has_icosahedral_symmetry(coords, elements, tol):
            return 'Ih' if has_inversion_center(coords, elements, tol) else 'I'

    # Check for dihedral and cyclic groups
    if max_n > 1:
        if has_dihedral_symmetry(coords, max_n, tol):
            if has_horizontal_mirror_plane(coords, tol):
                return f'D{max_n}h'
            elif has_diagonal_mirror_planes(coords, max_n, tol):
                return f'D{max_n}d'
            else:
                return f'D{max_n}'
        else:
            if has_vertical_mirror_planes(coords, max_n, tol):
                return f'C{max_n}v'
            elif has_horizontal_mirror_plane(coords, tol):
                return f'C{max_n}h'
            else:
                return f'C{max_n}'

    # Check for S2n (Ci or S4, S6, etc.)
    if has_s2n_axis(coords, max_n, tol):
        return f'S{2*max_n}'

    # Check for Cs and Ci
    if has_mirror_plane(coords, tol):
        return 'Cs'
    if has_inversion_center(coords, elements, tol):
        return 'Ci'

    return 'C1'

def is_linear(coords: np.ndarray, tol: float) -> bool:
    # Check if all atoms are collinear
    v1 = coords[1] - coords[0]
    for i in range(2, len(coords)):
        v2 = coords[i] - coords[0]
        if np.linalg.norm(np.cross(v1, v2)) > tol:
            return False
    return True

def has_inversion_center(coords: np.ndarray, elements: list, tol: float) -> bool:
    # Check if there's an atom at -r for every atom at r
    for i, atom in enumerate(coords):
        inverted_atom = -atom
        distances = np.linalg.norm(coords - inverted_atom, axis=1)
        if not np.any(distances < tol):
            return False
        matched_atom_idx = np.argmin(distances)
        if elements[i] != elements[matched_atom_idx]:
            return False
    return True

def has_c_n_axis(coords: np.ndarray, n: int, tol: float) -> bool:
    # Check for Cn axis by rotating around z-axis and checking equivalence
    angle = 2 * np.pi / n
    rotated_coords = rotate_coords(coords, angle, [0, 0, 1])
    return are_coords_equivalent(coords, rotated_coords, elements, tol)

def has_tetrahedral_symmetry(coords: np.ndarray, elements: list, tol: float) -> bool:
    # Simplified check; actual implementation requires more comprehensive symmetry analysis
    return has_c3_axes(coords, tol) and has_c2_axes(coords, tol)

def has_octahedral_symmetry(coords: np.ndarray, elements: list, tol: float) -> bool:
    # Simplified; actual implementation requires detailed symmetry analysis
    return has_c4_axes(coords, tol) and has_c3_axes(coords, tol)

def has_icosahedral_symmetry(coords: np.ndarray, elements: list, tol: float) -> bool:
    # Simplified; detailed analysis required for accurate detection
    return has_c5_axes(coords, tol) and has_c3_axes(coords, tol)

def has_dihedral_symmetry(coords: np.ndarray, n: int, tol: float) -> bool:
    # Check for Dn by verifying C2 axes perpendicular to Cn
    c_n_axis = [0, 0, 1]  # Assuming Cn is along z-axis
    c2_axis = [1, 0, 0]  # Example C2 axis
    rotated_c2_axis = rotate_vector(c2_axis, 2 * np.pi / n / 2, c_n_axis)
    rotated_coords = rotate_coords(coords, 2 * np.pi / n / 2, c_n_axis)
    return are_coords_equivalent(coords, rotated_coords, elements, tol)

def has_vertical_mirror_planes(coords: np.ndarray, n: int, tol: float) -> bool:
    # Check for sigma_v by reflecting across planes containing Cn (z-axis)
    for i in range(n):
        angle = i * 2 * np.pi / n
        normal = rotate_vector([1, 0, 0], angle, [0, 0, 1])
        reflected_coords = reflect_coords(coords, normal)
        if are_coords_equivalent(coords, reflected_coords, elements, tol):
            return True
    return False

def has_horizontal_mirror_plane(coords: np.ndarray, tol: float) -> bool:
    # Check for sigma_h by reflecting across xy-plane
    reflected_coords = coords.copy()
    reflected_coords[:, 2] *= -1
    return are_coords_equivalent(coords, reflected_coords, elements, tol)

def has_diagonal_mirror_planes(coords: np.ndarray, n: int, tol: float) -> bool:
    # Check for sigma_d by reflecting across planes between C2 axes
    c_n_axis = [0, 0, 1]
    c2_axis = [1, 0, 0]
    for i in range(n):
        angle = (i + 0.5) * 2 * np.pi / n
        normal = rotate_vector(c2_axis, angle, c_n_axis)
        reflected_coords = reflect_coords(coords, normal)
        if are_coords_equivalent(coords, reflected_coords, elements, tol):
            return True
    return False

def has_s2n_axis(coords: np.ndarray, n: int, tol: float) -> bool:
    # Check for S2n by improper rotation
    angle = 2 * np.pi / (2 * n)
    rotated_coords = rotate_coords(coords, angle, [0, 0, 1])
    reflected_coords = rotated_coords.copy()
    reflected_coords[:, 2] *= -1
    return are_coords_equivalent(coords, reflected_coords, elements, tol)

def has_mirror_plane(coords: np.ndarray, tol: float) -> bool:
    # Check for any mirror plane
    normals = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    for normal in normals:
        reflected_coords = reflect_coords(coords, normal)
        if are_coords_equivalent(coords, reflected_coords, elements, tol):
            return True
    return False

def are_coords_equivalent(coords1: np.ndarray, coords2: np.ndarray, elements: list, tol: float) -> bool:
    # Check if two sets of coordinates are equivalent under permutation
    if len(coords1) != len(coords2):
        return False

    coords1 = coords1[np.argsort(np.linalg.norm(coords1, axis=1))]
    coords2 = coords2[np.argsort(np.linalg.norm(coords2, axis=1))]

    for i in range(len(coords1)):
        distance = np.linalg.norm(coords1[i] - coords2[i])
        if distance > tol or elements[i] != elements[i]:  # elements[i] is always compared to itself here; fix needed
            return False
    return True

def rotate_coords(coords: np.ndarray, angle: float, axis: list) -> np.ndarray:
    # Rotate coordinates around given axis by angle (radians)
    axis = np.array(axis) / np.linalg.norm(axis)
    rotated_coords = np.zeros_like(coords)
    for i, coord in enumerate(coords):
        rotated_coords[i] = rotate_vector(coord, angle, axis)
    return rotated_coords

def rotate_vector(v: np.ndarray, angle: float, axis: np.ndarray) -> np.ndarray:
    # Rotate a vector around given axis by angle (radians)
    axis = axis / np.linalg.norm(axis)
    return v * np.cos(angle) + np.cross(axis, v) * np.sin(angle) + axis * np.dot(axis, v) * (1 - np.cos(angle))

def reflect_coords(coords: np.ndarray, normal: np.ndarray) -> np.ndarray:
    # Reflect coordinates across a plane with given normal
    normal = normal / np.linalg.norm(normal)
    reflected_coords = coords - 2 * np.outer(np.dot(coords, normal), normal)
    return reflected_coords

def has_c3_axes(coords: np.ndarray, tol: float) -> bool:
    # Simplified check for C3 axes; actual implementation requires detailed analysis
    return has_c_n_axis(coords, 3, tol)

def has_c4_axes(coords: np.ndarray, tol: float) -> bool:
    return has_c_n_axis(coords, 4, tol)

def has_c5_axes(coords: np.ndarray, tol: float) -> bool:
    return has_c_n_axis(coords, 5, tol)

def has_c2_axes(coords: np.ndarray, tol: float) -> bool:
    return has_c_n_axis(coords, 2, tol)

def has_s4_axes(coords: np.ndarray, tol: float) -> bool:
    return has_s2n_axis(coords, 2, tol)

